quests[36842] = { id = 36842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer zweiter Arbeitsauftrag für Juwelierskunst", description = "Erteilt meiner Gehilfin einen weiteren Auftrag. Sobald er fertig ist, könnt Ihr ihn hier abholen.", sourceObjective = "Erteilt einen Arbeitsauftrag und holt ihn nach Abschluss ab.\n\nIhr könnt den Fortschritt über das Garnisonsberichtsfenster verfolgen, das über die Schaltfläche auf der Minikarte aufrufbar ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[36843] = { id = 36843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie kamen von oben", description = "Bitte, <Reisender/Reisende>, ich brauche Eure Hilfe.\n\nAruuna, meine Heimat, wurde von den Arakkoa zerstört. Sie stießen von ihren Spitzen herab und töteten jeden, der zu fliehen versuchte. Meine Familie... hat es nicht hinausgeschafft.\n\nMein Bruder Barum blieb zurück, um in dem Chaos seine Tochter zu finden. Ich flehe Euch an, bitte geht nach Aruuna und sucht nach Barum.\n\nEr ist alles, was ich noch an Familie habe.", sourceObjective = "Findet Kristallformer Barum in der Nähe von Aruuna in Talador.", completion = "Akhan lebt? Das Licht segne uns. Endlich gute Nachrichten!", sourceObjectiveStatus = "unverified-source-field" }
quests[36845] = { id = 36845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer zweiter Arbeitsauftrag für Schneiderei", description = "Erteilt meiner Tochter einen weiteren Auftrag. Sobald er fertig ist, könnt Ihr ihn hier abholen.", sourceObjective = "Erteilt einen Arbeitsauftrag und holt ihn nach Abschluss ab.\n\nIhr könnt den Fortschritt über das Garnisonsberichtsfenster verfolgen, das über die Schaltfläche auf der Minikarte aufrufbar ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[36846] = { id = 36846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 082 - Spirit's Gift" }
quests[36847] = { id = 36847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires Ogre Gateway - Tracking" }
quests[36848] = { id = 36848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogerportale", description = "Auf Draenor existieren sechs einzigartige Tore, die schon vor Urzeiten von Ogermagiern errichtet wurden. Wir haben herausgefunden, dass sie ihre Kräfte im Laufe der vielen Jahrhunderte nicht verloren haben.\n\nWenn Ihr genug Ogerportalsteine einsammeln könnt, um eines dieser uralten Tore zu aktivieren, können wir ein Portal von Eurer Garnison zu diesem Standort einrichten.", sourceObjective = "Sammelt 25 Ogerportalsteine und benutzt sie zur Aktivierung eines Ogerportals in Draenor.", completion = "Eure Mühen sollen nicht umsonst gewesen sein, {name}. Die uralten Portale stehen Euch jetzt zur Verfügung.", sourceObjectiveStatus = "unverified-source-field" }
