quests[36860] = { id = 36860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf das Vergessene Anzuversteck" }
quests[36861] = { id = 36861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werkstatt Quetschpfeif", description = "Kommandant, heute Morgen ist ein Goblinkurier bei uns eingetroffen.\n\nEr sagte, er kommt aus einer Siedlung in den Spitzen von Arak, die sich Werkstatt Quetschpfeif nennt. Man bittet dort wegen irgendeiner Naturkatastrophe um unsere Hilfe.\n\nWenn wir ihr Vertrauen gewinnen können, wäre das die Mühe wert. Begebt Euch dorthin und schaut nach, welche Hilfe wir leisten können.\n\nIch habe bereits mit dem Flugmeister gesprochen, der einen Sonderflug für Euch dorthin veranlasst hat.", sourceObjective = "Sprecht mit Dungar Trinkfest, um Euren Flug zur Werkstatt Quetschpfeif anzutreten.", completion = "Heh, Ihr seid von dieser Allianzbasis, richtig?\n\nIch bin froh, dass Ihr die Reise angetreten habt, wir können hier nämlich wirklich Eure Hilfe brauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[36862] = { id = 36862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werkstatt Quetschpfeif", description = "Kommandant, ein Kurier ist heute Morgen eingetroffen.\n\nEr sagte, er kommt aus einer Goblinsiedlung in den Spitzen von Arak, die sich Werkstatt Quetschpfeif nennt. Man bittet dort wegen irgendeiner Naturkatastrophe um unsere Hilfe.\n\nWir haben zwar nur wenig Leute, aber wenn wir ihr Vertrauen gewinnen können, bekommen wir vielleicht einen wertvollen Verbündeten.\n\nBegebt Euch dorthin und schaut nach, welche Hilfe wir leisten können. Ich habe bereits mit dem Flugmeister gesprochen, der einen Sonderflug für Euch dorthin veranlasst hat.", sourceObjective = "Sprecht mit Bron Himmelshorn, um Euren Flug zur Werkstatt Quetschpfeif anzutreten.", completion = "Heh, Ihr seid doch von dieser Hordenbasis, richtig?\n\nIch bin froh, dass Ihr die Reise angetreten habt, wir können hier nämlich wirklich Eure Hilfe brauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[36863] = { id = 36863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Iron Horde Munitions" }
quests[36864] = { id = 36864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht tief genug für ein Grab", sourceObjective = "Ich muss schon sagen, ich hätte nie erwartet, den Oberkommandanten der Horde in einer Garnison der Allianz zu sehen.\n\nNatürlich hätte ich auch nie erwartet, dass ich bei einer Aufklärungsmission für die Dunkle Fürstin erwischt und zum Verrecken in ein Loch gestopft werden würde.\n\nOhne Eure Hilfe komme ich offensichtlich nie hier raus. Also werde ich Euch dienen, wenn Ihr mir helft. Für mich allein zu arbeiten hat mir sowieso nie viel Freude bereitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[36865] = { id = 36865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "UBRS Event Dungeon Reward Quest" }
quests[36866] = { id = 36866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lower Blackrock Spires Reward Quest" }
quests[36867] = { id = 36867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lower Blackrock Spires Bonus Reward Quest" }
quests[36870] = { id = 36870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nat ködern", description = "Ihr habt jetzt genug Erfahrung mit dem Angeln in Draenor gewonnen, sodass wir nun versuchen können, Nat Pagle zu überreden, sich uns hier anzuschließen.\n\nWenn wir Nat wirklich überzeugen wollen, dann müssen wir ihm einen echten Beweis für die unglaublichen Fangmöglichkeiten hier in Draenor präsentieren. Geht zu den örtlichen Gewässern hier im Schattenmondtal und versucht es dort. Die Perfektionierung Eurer Fähigkeiten in Draenor wird sich jetzt bestimmt bezahlt machen.", sourceObjective = "Fangt eine Arkanforelle im Schattenmondtal und bringt sie zu Segumi.", progress = "Habt Ihr etwas Vernünftiges gefunden?", completion = "Der ist perfekt... So einen Fisch kann niemand einfach abtun, erst recht nicht jemand wie Nat!", sourceObjectiveStatus = "unverified-source-field" }
quests[36872] = { id = 36872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Austin's Folly" }
quests[36874] = { id = 36874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsherr von Draenor", description = "Durotan...\n\n<Raza'kul spuckt aus.>\n\nEr versteckt sich hinter seiner weißen Friedensflagge und hofft, dass er unsere Todfeinde mit Diplomatie auf unsere Seite bringen kann.\n\nDiese Feinde, die unsere Heimat besetzt und uns aus dem Land unserer Ahnen vertrieben haben.\n\nBlut für Blut. Das ist das Einzige, was mir beim Anblick der Draenei und ihrer neu entdeckten Freundschaft mit Feiglingen in den Kopf kommt.\n\nHelft mir doch dabei, unsere Feinde zu zerschmettern. Gemeinsam werden wir diesen geheiligten Boden mit den Knochen der Allianz bedecken und uns Tribute verdienen, die einem Kriegshäuptling würdig wären!\n\nKehrt hierher zurück, wenn Euer Blutdurst gestillt ist.", sourceObjective = "Tötet gegnerische Spielercharaktere in PvP-Kämpfen, um 20 gebrochene Knochen zu verdienen, und platziert dann eine Opfergabe am Altar der Knochen, um einen Tribut des Eroberers zu erhalten.", completion = "Wir könnten vom Himmelsanbruch bis zum Himmelsuntergang kämpfen und unsere Arbeit würde doch nie ein Ende finden. Und wenn unsere Erfolge am Ende aller Tage gemessen werden, wird unsere Stärke nur an der Blutspur, die wir hinter uns gelassen haben, erkannt werden. Aus diesem Grund sollt Ihr nie aufhören, jene zu töten, die uns und unsere Familien bedrohen.\n\nVersprecht es mir, {name}.\n\nHört. Niemals. Auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[36876] = { id = 36876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsherr von Draenor", description = "Die Exarchen streiten untereinander über belanglose Probleme, während unser Volk von abscheulichen Orcs heimgesucht und umgebracht wird. Wenn sie nicht ihre Fäuste im Widerstand gegen unsere Feinde erheben, werde ich es tun.\n\nIch möchte Eurer Allianz beitreten und diese Welt von der Horde befreien. JEDER HORDE – \"Eisern\" oder nicht.\n\nDieser Altar der Gebeine, auf dem ich hier stehe, repräsentiert den Ruhm im Kampfe gegen unseren Feind, die Horde. Platziert eine Opfergabe darauf und verdient einen Tribut eines Eroberers, der Eurem unablässigen Blutdurst würdig ist.\n\nTötet. Sie. Alle.", sourceObjective = "Tötet gegnerische Spielercharaktere in PvP-Kämpfen, um 20 gebrochene Knochen zu verdienen, und platziert dann eine Opfergabe am Altar der Knochen, um einen Tribut des Eroberers zu erhalten.", completion = "Ein Anfang ist es, so viel ist sicher. Doch es muss noch viel getan werden, wenn Draenor gerettet werden soll. Zeigt keine Gnade, denn auch sie werden dies nicht tun.\n\nDie einzigen Kriegsfürsten, die auf Draenor verbleiben, werden wir beide sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[36877] = { id = 36877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Tormmok" }
quests[36878] = { id = 36878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: The Light of Karabor" }
quests[36879] = { id = 36879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Dusty Lockbox" }
quests[36880] = { id = 36880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Sneevel" }
quests[36881] = { id = 36881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warlords of Draenor: Das Dunkle Portal", description = "{name}, richtig? Ich bin froh, dass Ihr hier seid. <Ein fähiger/Eine fähige:c> {class} wie Ihr kommt uns gerade recht.\n\nIch stelle ein Bündnis der mächtigsten Helden aus Azeroth zusammen, die sich durch dieses Dunkle Portal begeben und die Invasion der Eisernen Horde aufhalten sollen. Das ist vielleicht die einzige Möglichkeit, Azeroth vor dem Untergang zu bewahren.\n\nSchließt Ihr Euch uns an?", sourceObjective = "Sprecht mit Erzmagier Khadgar am Fuße des Dunklen Portals in den Verwüsteten Landen.", completion = "Meiner Meinung nach sind wir am richtigen Ort gelandet.", sourceObjectiveStatus = "unverified-source-field" }
quests[36882] = { id = 36882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Angler kehrt zurück", description = "Was ist das für eine Spezies? Eine Arkanforelle, sagt Ihr? Von solch einem Fisch habe ich noch nie gehört, geschweige denn, selbst einen zu Gesicht bekommen!\n\nIch muss mehr von diesen Fischen sehen, denn genau für so etwas lebe ich schließlich! Und wenn das Angeln dort so gut ist, wie Ihr sagt, dann werde ich mir diese Gelegenheit auf keinen Fall entgehen lassen. Nehmt diese Seite aus meinem Tagebuch als Beweis, dass Ihr mich gefunden habt. Wir treffen uns dann in Eurer Garnison.", sourceObjective = "Kehrt zu Segumi zurück und zeigt ihm Nats Tagebuchseite als Beweis, dass Ihr ihn gefunden habt.", progress = "Ihr habt Nat gefunden? Den echten Nat Pagle?!", completion = "Wir werden sicher ein paar Riesenfische fangen, wenn Nat erst mal hier ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[36884] = { id = 36884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgenschnauze", progress = "HABT IHR ETWAS FÜR MICH, MUFIN?", completion = "OHH, SO WEICH. UND NOCH GANZ WARM. GUTE ARBEIT!" }
quests[36885] = { id = 36885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogre Waygate" }
