quests[36887] = { id = 36887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette 029 - Hermit Palefur" }
quests[36889] = { id = 36889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Jäger und Gejagte", description = "Wir sind von Feinden umgeben und mit jedem neuen Tag, werden es mehr. Es ist an der Zeit, dass wir einen entschlossenen Schlag gegen ihre Armeen ausführen, Champion.\n\nUm mich herum seht Ihr Abbilder unserer meistgehassten Gegner. Ihr werdet sie zu Fall bringen, {name}. Ihr werdet zur Nemesis werden, und sie werden vor Angst fliehen, sobald sie Euch erblicken.\n\nWählt nun das Ziel Eurer Wut und verbrennt das Bildnis des Volkes, auf das Ihr es abgesehen habt. Sprecht erneut mit mir, wenn Ihr Eure Wahl getroffen habt.", sourceObjective = "Verbrennt ein Nemesisbildnis beim Heiligtum des Gladiators und sprecht dann mit Raza'kul.", completion = "Eine letzte Warnung: Nachdem Ihr diese Wahl getroffen habt, könnt Ihr sie nicht rückgängig machen oder eine neue Wahl treffen, bevor Ihr Eure Mission abgeschlossen habt.\n\nWenn Ihr bei Eurer Wahl sicher seid, wird Euch auch der Sieg sicher sein.\n\nErfüllt die Herzen Eurer Widersacher mit Furcht! Für die Horde. Für Draenor.", sourceObjectiveStatus = "unverified-source-field" }
quests[36890] = { id = 36890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis Flag, Human/Orc" }
