quests[36896] = { id = 36896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis Flag, Pandaren (A/H)" }
quests[36897] = { id = 36897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Zum Tod werden", description = "Ihr habt Eure Opfer ausgewählt, und sie werden sicherlich bald Euren gnadenlosen Zorn zu spüren bekommen, aber zunächst müsst Ihr in die Wildnis Draenors vordringen und in einem Kampf auf Leben und Tod einem Menschen das noch schlagende Herz aus der Brust reißen. Kehrt mit Eurer Beute hierher zurück.\n\nDurch das Herz Eures Feinds werden sich die Geister mit Euren Sinnen verbinden und Euch das zweite Gesicht sowie ein scharfes Gehör verleihen, damit Ihr Eure Beute verfolgen und Eure Überlegenheit deutlich machen könnt.", sourceObjective = "Tötet einen menschlichen Spielercharakter in PvP-Kämpfen in Draenor und beschafft dessen Menschenherz.", progress = "Habt Ihr das Herz eines würdigen Feindes beschafft?", completion = "Mit diesem Herz könnt Ihr Dinge sehen und hören, wie es sonst nur die großen Geister können. Euer Feind wird nicht in der Lage sein, sich vor Euren unnachgiebigen Angriffen zu verstecken.", sourceObjectiveStatus = "unverified-source-field" }
