quests[36907] = { id = 36907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Defense of Karabor - Celebration Scene Finished" }
quests[36911] = { id = 36911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training eines Talbuks", description = "Wenn wir anfangen wollen, unsere Patrouillen in die Wildnis auszusenden, brauchen wir schnelle Reittiere für unsere Truppen. Wir können Jungtiere fangen und für ihr Training herbringen. Später werden sie dann zu bemerkenswerten Kriegsbestien.\n\nTalbuks gehören zu den schnellsten Kreaturen von Draenor, und das macht sie unheimlich schwer einzufangen. Nehmt dieses Talbuklasso und begebt Euch ins Schattenmondtal. Steigt auf Euer Reittier und fangt einen der jungen Talbuks mit dem Lasso und folgt ihm dann, bis er gezähmt ist. Lasst ihn nicht zu weit weglaufen!", sourceObjective = "Fangt ein Silberfelljungtier mit dem Talbuklasso ein und folgt ihm, bis es gezähmt ist.", completion = "Dieser Talbuk hat sich vorerst zur Ruhe gelegt. Er braucht ein wenig Schlaf und Fürsorge, bevor er für die nächste Phase seines Trainings bereit ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[36912] = { id = 36912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grollhuf an der Leine", description = "Seid gegrüßt. Mir wurde gesagt, Ihr hättet Bedarf für einen Meister der Tiere. Ich komme von den eisigen Hängen Nordends, um endlich den Schnee aus meinem Pelz zu schütteln.\n\nIn diesem wilden Land gibt es viele Kreaturen, die wir zähmen können, um unsere Truppen mit beeindruckenden Kriegsreittieren auszustatten. Der gewaltige Grollhuf erinnert mich an die Mammuts aus meiner Heimat. Nehmt dieses Lasso und macht Euch zu den nördlichen Ausläufern des Frostfeuergrats auf. Sitzt auf und fangt damit eines der Jungtiere.", sourceObjective = "Fangt einen jungen Eishuf mit dem Grollhuflasso ein und folgt ihm, bis er gezähmt ist.", completion = "Ich habe den Grollhuf für die Nacht mit Streu versorgt. Er muss sich ausruhen, ehe er ausgebildet werden kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[36913] = { id = 36913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ergreifung eines Ebers", description = "Habt Ihr die Eber gesehen, die es hier gibt? Die sind größer als ich! Sollen wir uns nicht einen davon schnappen?\n\nIhr müsst für diese Aufgabe nach Gorgrond. Draußen in den einsamsten Regionen werdet Ihr die finden, die wir suchen.", sourceObjective = "Fangt einen jungen Felshauer mit dem Eberlasso ein und folgt ihm, bis er gezähmt ist.", completion = "Der Eber hat sich ins Heu gestürzt. Wir lassen ihn ein wenig ruhen, bevor wir ihn weiter ausbilden.", sourceObjectiveStatus = "unverified-source-field" }
quests[36914] = { id = 36914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolf am Wickel", description = "Mit dem Nächsten werdet Ihr an Eure Grenzen stoßen, Kommandant. Der Wolf ist das wildeste Tier in ganz Draenor.\n\nDie Wölfe von Nagrand, Reittiere des sagenumwobenen Kriegshymnenklans, können einen Mann im Handumdrehen in Stücke reißen. Außerdem sind sie schneller und beweglicher als alles, was Ihr bisher zu Gesicht bekommen habt.\n\nHier ist Euer Lasso. Viel Glück und lasst Euch nicht umbringen!", sourceObjective = "Fangt einen jungen Knurrer mit dem Wolfslasso ein und folgt ihm, bis er gezähmt ist.", completion = "Um ein Haar hätte er mich gebissen, jetzt schläft er aber zufrieden. Ein Wolf in meinem Stall! Wer hätte das gedacht?", sourceObjectiveStatus = "unverified-source-field" }
quests[36915] = { id = 36915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endlich ein Elekk", description = "Ihr seid ziemlich gut im Zähmen von Tieren, das muss man Euch lassen. Was kommt als Nächstes dran?\n\nWir hatten groß und wir hatten scharf. Wie wäre es mit groß UND scharf? Damit meine ich Elekks.\n\nWeit draußen in den fruchtbaren Ebenen von Nagrand findet Ihr die besten Exemplare, die diese Welt zu bieten hat. Greift Euch einen von den jüngeren Elekk, dann werden wir sehen, ob es uns gelingt, ihn so auszubilden wie einst die Draenei.", sourceObjective = "Fangt einen jungen Wiesentrampler mit dem Elekklasso ein und folgt ihm, bis er gezähmt ist.", completion = "Ziemlich groß, aber er passt in den Stall! Er ruht sich aus. Morgen werden wir uns über seine Ausbildung unterhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[36916] = { id = 36916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grollhuf an der Leine", description = "Hoch im Norden, in den eisigen Gipfeln des Frostfeuergrats, findet Ihr den wolligen Grollhuf.\n\nDiese Tiere sind robust und wehren sich erbittert, wenn sie in die Enge getrieben werden. Erwartet nicht, eins kampflos zähmen zu können.\n\nHier ist ein Lasso. Versucht, es zu zähmen, ehe es Euch das Seil aus den Händen reißt.", sourceObjective = "Fangt einen jungen Eishuf mit dem Grollhuflasso ein und folgt ihm, bis er gezähmt ist.", completion = "War es kalt dort oben? Dieser Kerl scheint die Wärme jedenfalls zu genießen: Er ist schon eingeschlafen!", sourceObjectiveStatus = "unverified-source-field" }
quests[36917] = { id = 36917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training eines Talbuks", description = "Das nächste Tier ist eines der schnellsten auf Draenor, es wird jedoch Euer Können beim Infiltrieren des Feindgebiets auf die Probe stellen.\n\nIhr findet den jungen Talbuk auf den blumenbewachsenen Hügeln des Schattenmondtals. Nehmt dieses Talbuklasso und macht Euch auf den Weg.\n\nWenn Ihr einem begegnet, sitzt auf, werft dieses Seil und folgt ihm so lange, bis er zahm ist. Waidmanns Heil!", sourceObjective = "Fangt ein Silberfelljungtier mit dem Talbuklasso ein und folgt ihm, bis es gezähmt ist.", completion = "Dem Talbuk scheint es gut zu gehen. Lasst ihn ausruhen, ehe Ihr seine Ausbildung fortsetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[36918] = { id = 36918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fangt eine Flussbestie", description = "Bei diesem nächsten Tier war ich mir nicht so sicher. Wie sich aber herausstellt, hat es einen wichtigen strategischen Zweck. Die Flussbestie fühlt sich im Wasser richtig wohl!\n\nDie besten Exemplare findet Ihr in Talador in der Umgebung der Abendlichtinsel. Haltet nach riesigen Brocken Ausschau, die im Wasser treiben.\n\nVersucht, trocken zu bleiben!", sourceObjective = "Fangt einen jungen Flussfläzer mit dem Flussbestienlasso ein und folgt ihm, bis er gezähmt ist.", completion = "Ich habe sie schon abgetrocknet. Sehen wir uns morgen an, ob sich dieses Vieh ausbilden lässt.", sourceObjectiveStatus = "unverified-source-field" }
quests[36919] = { id = 36919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talador - Shore Vignette - Murloc Boss" }
quests[36920] = { id = 36920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von innen heraus", description = "Einige unserer Dämonenjäger, Kor'vas Blutdorn und Cyana Nachtgleve, sind mit einer kleinen Streitmacht der Illidari nach Faronaar übergesetzt. Ihre Mission war es, die Legion von innen heraus zu schwächen.\n\nIch habe schon eine Weile nichts von ihnen gehört.\n\nEs wäre das Beste, wenn Ihr sie finden und zum Erfolg führen könntet. Einverstanden?", sourceObjective = "Sucht nach Kor'vas Blutdorn auf Faronaar am Triumphposten.", completion = "Ein Freund, wie es scheint.\n\nTraut Kayn uns nicht zu, damit fertigzuwerden? Vielleicht hat er dieses Mal recht.", sourceObjectiveStatus = "unverified-source-field" }
quests[36921] = { id = 36921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Menschentöter", description = "<Raza'kul übergibt Euch das blutige Herz.>\n\nDas Ritual ist abgeschlossen. Eure Nemesis ist dem Tode geweiht.\n\nEure Arbeit, diese Welt vom Feind zu befreien, beginnt jetzt. Tötet alle Menschen, die sich trotzig der Horde entgegenstellen. Möge ihr Tod als Warnung für den Rest der Allianz dienen: Sie verlassen Draenor, oder sie werden sterben.\n\nKehrt zurück, wenn Ihr Euren Rachedurst mit dem Blut der Menschen gestillt habt.\n\nBesiegt Euren Feind und werdet als Menschentöter bekannt. Versagt, und Ihr werdet ein Nichts sein.", sourceObjective = "Tötet 500 menschliche Spielercharaktere in PvP-Kämpfen in Draenor.", sourceObjectiveStatus = "unverified-source-field" }
quests[36922] = { id = 36922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "zzzzTITEL TEST" }
quests[36923] = { id = 36923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Zum Tod werden", description = "Ihr habt Eure Opfer ausgewählt, und sie werden sicherlich bald Euren gnadenlosen Zorn zu spüren bekommen, aber zunächst müsst Ihr in die Wildnis Draenors vordingen und in einem Kampf auf Leben und Tod einem Zwerg das noch schlagende Herz aus der Brust reißen. Kehrt mit Eurer Beute hierher zurück.\n\nDurch das Herz Eures Feinds werden sich die Geister mit Euren Sinnen verbinden und Euch das zweite Gesicht sowie ein scharfes Gehör verleihen, damit Ihr Eure Beute verfolgen und Eure Überlegenheit deutlich machen könnt.", sourceObjective = "Tötet einen Zwergenspielercharakter in PvP-Kämpfen in Draenor und beschafft dessen Zwergenherz.", sourceObjectiveStatus = "unverified-source-field" }
quests[36924] = { id = 36924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Zwergenhenker", description = "<Raza'kul übergibt Euch das blutige Herz.>\n\nDas Ritual ist abgeschlossen. Eure Nemesis ist dem Tode geweiht.\n\nEure Arbeit, diese Welt vom Feind zu befreien, beginnt jetzt. Tötet alle Zwerge, die sich trotzig der Horde entgegenstellen. Möge ihr Tod als Warnung für den Rest der Allianz dienen: Sie verlassen Draenor, oder sie werden sterben.\n\nKehrt zurück, wenn Ihr Euren Rachedurst mit dem Blut der Zwerge gestillt habt.\n\nBesiegt Euren Feind und werdet als Zwergenhenker bekannt. Versagt, und Ihr werdet ein Nichts sein.", sourceObjective = "Tötet 500 Zwergenspielercharaktere in PvP-Kämpfen in Draenor.", sourceObjectiveStatus = "unverified-source-field" }
quests[36925] = { id = 36925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Zum Tod werden", description = "Ihr habt Eure Opfer ausgewählt, und sie werden sicherlich bald Euren gnadenlosen Zorn zu spüren bekommen, aber zunächst müsst Ihr in die Wildnis Draenors vordingen und in einem Kampf auf Leben und Tod einem Gnom das noch schlagende Herz aus der Brust reißen. Kehrt mit Eurer Beute hierher zurück.\n\nDurch das Herz Eures Feinds werden sich die Geister mit Euren Sinnen verbinden und Euch das zweite Gesicht sowie ein scharfes Gehör verleihen, damit Ihr Eure Beute verfolgen und Eure Überlegenheit deutlich machen könnt.", sourceObjective = "Tötet einen Gnomenspielercharakter in PvP-Kämpfen in Draenor und beschafft dessen Gnomenherz.", sourceObjectiveStatus = "unverified-source-field" }
quests[36926] = { id = 36926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Gnomenschreck", description = "<Raza'kul übergibt Euch das blutige Herz.>\n\nDas Ritual ist abgeschlossen. Eure Nemesis ist dem Tode geweiht.\n\nEure Arbeit, diese Welt vom Feind zu befreien, beginnt jetzt. Tötet alle Gnome, die sich trotzig der Horde entgegenstellen. Möge ihr Tod als Warnung für den Rest der Allianz dienen: Sie verlassen Draenor, oder sie werden sterben.\n\nKehrt zurück, wenn Ihr Euren Rachedurst mit dem Blut der Gnome gestillt habt.\n\nBesiegt Euren Feind und werdet als Gnomenschreck bekannt. Versagt, und Ihr werdet ein Nichts sein.", sourceObjective = "Tötet 500 Gnomenspielercharaktere in PvP-Kämpfen in Draenor.", sourceObjectiveStatus = "unverified-source-field" }
quests[36927] = { id = 36927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Zum Tod werden", description = "Ihr habt Eure Opfer ausgewählt, und sie werden sicherlich bald Euren gnadenlosen Zorn zu spüren bekommen, aber zunächst müsst Ihr in die Wildnis Draenors vordingen und in einem Kampf auf Leben und Tod einem Worgen das noch schlagende Herz aus der Brust reißen. Kehrt mit Eurer Beute hierher zurück.\n\nDurch das Herz Eures Feinds werden sich die Geister mit Euren Sinnen verbinden und Euch das zweite Gesicht sowie ein scharfes Gehör verleihen, damit Ihr Eure Beute verfolgen und Eure Überlegenheit deutlich machen könnt.", sourceObjective = "Tötet einen Worgenspielercharakter in PvP-Kämpfen in Draenor und beschafft dessen Worgenherz.", sourceObjectiveStatus = "unverified-source-field" }
quests[36928] = { id = 36928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Worgenjäger", description = "<Raza'kul übergibt Euch das blutige Herz.>\n\nDas Ritual ist abgeschlossen. Eure Nemesis ist dem Tode geweiht.\n\nEure Arbeit, diese Welt vom Feind zu befreien, beginnt jetzt. Tötet alle Worgen, die sich trotzig der Horde entgegenstellen. Möge ihr Tod als Warnung für den Rest der Allianz dienen: Sie verlassen Draenor, oder sie werden sterben.\n\nKehrt zurück, wenn Ihr Euren Rachedurst mit dem Blut der Worgen gestillt habt.\n\nBesiegt Euren Feind und werdet als Worgenjäger bekannt. Versagt, und Ihr werdet ein Nichts sein.", sourceObjective = "Tötet 500 Worgenspielercharaktere in PvP-Kämpfen in Draenor.", sourceObjectiveStatus = "unverified-source-field" }
quests[36929] = { id = 36929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Zum Tod werden", description = "Ihr habt Eure Opfer ausgewählt, und sie werden sicherlich bald Euren gnadenlosen Zorn zu spüren bekommen, aber zunächst müsst Ihr in die Wildnis Draenors vordingen und in einem Kampf auf Leben und Tod einem Draenei das noch schlagende Herz aus der Brust reißen. Kehrt mit Eurer Beute hierher zurück.\n\nDurch das Herz Eures Feinds werden sich die Geister mit Euren Sinnen verbinden und Euch das zweite Gesicht sowie ein scharfes Gehör verleihen, damit Ihr Eure Beute verfolgen und Eure Überlegenheit deutlich machen könnt.", sourceObjective = "Tötet einen Draeneispielercharakter in PvP-Kämpfen in Draenor und beschafft dessen Draeneiherz.", sourceObjectiveStatus = "unverified-source-field" }
quests[36930] = { id = 36930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Draeneivernichter", description = "<Raza'kul übergibt Euch das blutige Herz.>\n\nDas Ritual ist abgeschlossen. Eure Nemesis ist dem Tode geweiht.\n\nEure Arbeit, diese Welt vom Feind zu befreien, beginnt jetzt. Tötet alle Draenei, die sich trotzig der Horde entgegenstellen. Möge ihr Tod als Warnung für den Rest der Allianz dienen: Sie verlassen Draenor, oder sie werden sterben.\n\nKehrt zurück, wenn Ihr Euren Rachedurst mit dem Blut der Draenei gestillt habt.\n\nBesiegt Euren Feind und werdet als Draeneivernichter bekannt. Versagt, und Ihr werdet ein Nichts sein.", sourceObjective = "Tötet 500 Draeneispielercharaktere in PvP-Kämpfen in Draenor.", sourceObjectiveStatus = "unverified-source-field" }
quests[36931] = { id = 36931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Zum Tod werden", description = "Ihr habt Eure Opfer ausgewählt, und sie werden sicherlich bald Euren gnadenlosen Zorn zu spüren bekommen, aber zunächst müsst Ihr in die Wildnis Draenors vordingen und in einem Kampf auf Leben und Tod einem Nachtelfen das noch schlagende Herz aus der Brust reißen. Kehrt mit Eurer Beute hierher zurück.\n\nDurch das Herz Eures Feinds werden sich die Geister mit Euren Sinnen verbinden und Euch das zweite Gesicht sowie ein scharfes Gehör verleihen, damit Ihr Eure Beute verfolgen und Eure Überlegenheit deutlich machen könnt.", sourceObjective = "Tötet einen Nachtelfenspielercharakter in PvP-Kämpfen in Draenor und beschafft dessen Nachtelfenherz.", sourceObjectiveStatus = "unverified-source-field" }
quests[36932] = { id = 36932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Geißel der Kaldorei", description = "<Raza'kul übergibt Euch das blutige Herz.>\n\nDas Ritual ist abgeschlossen. Eure Nemesis ist dem Tode geweiht.\n\nEure Arbeit, diese Welt vom Feind zu befreien, beginnt jetzt. Tötet alle Nachtelfen, die sich trotzig der Horde entgegenstellen. Möge ihr Tod als Warnung für den Rest der Allianz dienen: Sie verlassen Draenor, oder sie werden sterben.\n\nKehrt zurück, wenn Ihr Euren Rachedurst mit dem Blut der Nachtelfen gestillt habt.\n\nBesiegt Euren Feind und werdet als Geißel der Kaldorei bekannt. Versagt, und Ihr werdet ein Nichts sein.", sourceObjective = "Tötet 500 Nachtelfenspielercharaktere in PvP-Kämpfen in Draenor.", completion = "Die Wahrheit über Eure Taten steht in Euren Augen. Euer Hunger nach dem Feind wurde gestillt mit Rufen nach Gnade und Strömen von Blut.\n\nNehmt Euren Platz als Geißel der Kaldorei ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[36933] = { id = 36933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Zum Tod werden", description = "Ihr habt Eure Opfer ausgewählt, und sie werden sicherlich bald Euren gnadenlosen Zorn zu spüren bekommen, aber zunächst müsst Ihr in die Wildnis Draenors vordingen und in einem Kampf auf Leben und Tod einem Pandaren das noch schlagende Herz aus der Brust reißen. Kehrt mit Eurer Beute hierher zurück.\n\nDurch das Herz Eures Feinds werden sich die Geister mit Euren Sinnen verbinden und Euch das zweite Gesicht sowie ein scharfes Gehör verleihen, damit Ihr Eure Beute verfolgen und Eure Überlegenheit deutlich machen könnt.", sourceObjective = "Tötet einen Pandarenspielercharakter in PvP-Kämpfen in Draenor und beschafft dessen Pandarenherz.", progress = "Habt Ihr das Herz eines würdigen Feindes beschafft?", completion = "Mit diesem Herz könnt Ihr Dinge sehen und hören, wie es sonst nur die großen Geister können. Euer Feind wird nicht in der Lage sein, sich vor Euren unnachgiebigen Angriffen zu verstecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[36934] = { id = 36934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Terror der Tushui", description = "<Raza'kul übergibt Euch das blutige Herz.>\n\nDas Ritual ist abgeschlossen. Eure Nemesis ist dem Tode geweiht.\n\nEure Arbeit, diese Welt vom Feind zu befreien, beginnt jetzt. Tötet alle Pandaren, die sich trotzig der Horde entgegenstellen. Möge ihr Tod als Warnung für den Rest der Allianz dienen: Sie verlassen Draenor, oder sie werden sterben.\n\nKehrt zurück, wenn Ihr Euren Rachedurst mit dem Blut der Pandaren gestillt habt.\n\nBesiegt Euren Feind und werdet als Terror der Tushui bekannt. Versagt, und Ihr werdet ein Nichts sein.", sourceObjective = "Tötet 500 Pandarenspielercharaktere in PvP-Kämpfen in Draenor.", sourceObjectiveStatus = "unverified-source-field" }
quests[36935] = { id = 36935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phantomtrank", description = "Jedes Mal, wenn man sich in Ashran umdreht, gerät man in Schwierigkeiten. Aber keine Angst, {name}, ich habe die perfekte Lösung entwickelt: meine ganz persönliche Version des beliebten Unsichtbarkeitstranks.\n\nMir fehlt nur noch eine Zutat: Höhlenpilze.\n\nZum Glück wächst eine Sorte davon hier in Ashran.", sourceObjective = "Bringt Tyra Silberblut 10 Geistertrüffel.", sourceObjectiveStatus = "unverified-source-field" }
quests[36936] = { id = 36936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Leorajh" }
quests[36937] = { id = 36937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talador - Bladefury Treasure - Burning Blade Cache" }
quests[36940] = { id = 36940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warnt Orgrimmar", description = "Die Eiserne Horde ist durch uns langsamer geworden, aber dieser Krieg ist noch lange nicht vorüber... Ich bleibe hier und gebe mir weiter Mühe, die Eiserne Horde aufzuhalten.\n\nDer Kriegshäuptling muss wissen, was wir hier heute erreicht haben und welcher Bedrohung wir uns in Zukunft gegenübersehen.\n\nEs wäre wohl das Beste, wenn Ihr persönlich Hochfürst Saurfang Bericht erstattet, {class}.", sourceObjective = "Sprecht mit Hochfürst Saurfang.", completion = "Das ist mehr Ärger, als ich mir vorgestellt habe. Die Eiserne Horde ist stark, aber niemand hat der wahren Horde etwas entgegenzusetzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[36941] = { id = 36941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erstattet dem König Bericht", description = "Die Eiserne Horde ist durch uns langsamer geworden, aber dieser Krieg ist noch lange nicht vorüber... Ich bleibe hier und gebe mir weiter Mühe, die Eiserne Horde aufzuhalten.\n\nDer König muss wissen, was wir hier heute erreicht haben und welcher Bedrohung wir uns in Zukunft gegenübersehen.\n\nEs wäre wohl das Beste, wenn Ihr persönlich König Wrynn Bericht erstattet, {name}.", sourceObjective = "Sprecht mit König Anduin Wrynn.", completion = "Es ist noch schlimmer, als ich dachte.\n\nDie Eiserne Horde erweist sich als große Bedrohung für unser Volk... Ich will kein weiteres Blutvergießen, aber ich fürchte, uns bleibt gar keine andere Wahl.\n\nWir brauchen einen Plan, bevor wir zuschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36942] = { id = 36942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soulbinder Aedraa" }
quests[36943] = { id = 36943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette 030 - Gaze" }
quests[36944] = { id = 36944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ergreifung eines Ebers", description = "Die großen Eber aus Gorgrond scheinen sowohl als Reittier als auch als ausgezeichnete Nahrungsquelle zu dienen. Einige davon in der Garnison zu haben, wäre gar keine dumme Idee.\n\nIch habe noch ein Seil für Euch gemacht, solltet Ihr versuchen wollen, einen zuzureiten. Seid vorsichtig, die Eiserne Horde ist in der Nähe.", sourceObjective = "Fangt einen jungen Felshauer mit dem Eberlasso ein und folgt ihm, bis er gezähmt ist.", completion = "Der Eber hat sich schnell mit dem Stall abgefunden. Scheinbar sind sie schon zum Teil domestiziert. Er wird etwas Zeit brauchen, um sich auszuruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36945] = { id = 36945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fangt eine Flussbestie", description = "Ich habe große Tiere gesehen, die sich langsam in den Flüssen Taladors treiben ließen. Man nennt sie, glaube ich, 'Flussbestien'.\n\nIhre Haut ist hart wie Stein und dennoch treiben sie gemächlich im Wasser. Ich würde gerne eins aus der Nähe sehen, falls Ihr in die Richtung geht. Tormak hat für Euch noch ein Seil hergestellt, wenn Ihr Interesse habt.", sourceObjective = "Fangt eine junge Flussbestie mit dem Flussbestienlasso ein und folgt ihr, bis sie gezähmt ist.", completion = "Ein beeindruckender Anblick, das muss ich wohl sagen. Groß und kräftig und doch so voller Luft. Morgen wird es zur Ausbildung bereit sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[36946] = { id = 36946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endlich ein Elekk", description = "Die Ebenen von Nagrand sind so üppig bewachsen und fruchtbar, wie ich es noch nie gesehen habe. Solltet Ihr jemals dort sein, werdet Ihr die kräftigsten Tiere zu Gesicht bekommen, die an diesem Ort leben.\n\nUnter ihnen ist der große Elekk. Ein prachtvolles Tier mit Hörnern, die größer werden können als Ihr oder ich.\n\nHier ist noch ein Seil, solltet Ihr Euch an einem solchen Tier versuchen wollen.", sourceObjective = "Fangt einen jungen Wiesentrampler mit dem Elekklasso ein und folgt ihm, bis er gezähmt ist.", completion = "Ein kräftiges Tier. Es hätte beinahe die Holzpfähle des Stalls umgeworfen. Wir werden mit der Ausbildung beginnen, sobald es erwacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[36947] = { id = 36947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Stärke", sourceObjective = "Ich habe hart trainiert, seit ich Euren Streitkräften beigetreten bin, Kommandant.\n\nLasst mich meine neue Stärke unter Beweis stellen, damit ich es wert bin, an Eurer Seite zu kämpfen. Alle werden bei unserem Anblick auf dem Schlachtfeld erzittern!Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
quests[36948] = { id = 36948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teileauktion", progress = "<Der Machtkristall dieser Einheit wurde entfernt. Wer dafür verantwortlich ist, hat auch vier andere Unterstützungsmodule herausgerissen.\n\nWenn Ihr all diese Gegenstände findet, könnt Ihr sie bestimmt wiederherstellen.>", completion = "Ihr könnt hören, wie sich die Energie in der Einheit aufbaut..." }
quests[36950] = { id = 36950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolf am Wickel", description = "Die Wölfe dieses Lands haben Kiefer aus Stahl. Kein Wunder, dass die Orcs sie für sich haben wollten.\n\nDennoch, tief in Nagrand gibt es junge Wölfe, die reif fürs Zähmen sind. Sie werden eine große Herausforderung für Euch darstellen, da sie schneller und geschickter sind, als jedes andere Tier im Land.\n\nHier ist Euer letztes Seil. Möge das Glück mit Euch sein.", sourceObjective = "Fangt einen jungen Knurrer mit dem Wolfslasso ein und folgt ihm, bis er gezähmt ist.", completion = "Ein beeindruckender Fang, Kommandant. Er wird sich einige Zeit ausruhen müssen, aber er wird sicher bald kampfhungrig sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[36951] = { id = 36951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exodus der Arakkoa", description = "Ich nehme an, Ihr kennt die Arakkoa, Kommandant? Ein Volk mächtiger fliegender Vogelmenschen. Extrem feindselig gegenüber Eindringlingen.\n\nBei manchen von ihnen sind die Flügel verkümmert, möglicherweise aufgrund einer Krankheit. Sie werden anscheinend aus der Gesellschaft der Arakkoa ausgestoßen. Man sieht sie hin und wieder in vergessenen Ruinen hausen oder an den Straßen billigen Schmuck verkaufen.\n\nEs sieht so aus, als hätte die Eiserne Horde die Arakkoa durch ihr Eindringen in ihr Gebiet aufgescheucht. Die Ausgestoßenen fliehen in Scharen.\n\nWir sollten mit ihnen Kontakt aufnehmen. Möglicherweise haben sie wertvolle Informationen.", sourceObjective = "Sprecht mit Azik in den Spitzen von Arak.", completion = "<Der Arakkoahändler mustert Euch von oben bis unten.>\n\nWir sind ganz gut ausgerüstet, was? Azik könnte wetten, dass Ihr jemand Wichtiges seid bei Eurem Volk.\n\nAber kommt doch näher, unterhaltet Euch einen Augenblick mit mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[36952] = { id = 36952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht nach Nagrand tragen", description = "**Streng vertraulich – Kommandant {name}**\n\nKriegshäuptling Durotan hat uns angewies'n, einen neuen Außenposten in Nagrand zu bau'n. Ich hab' dafür einige unserer Leute abgestellt.\n\nThrall hat uns bereits benachrichtigt, dass der Außenposten bald fertig is'. Er lässt Euch mitteilen, dass alles für Euch bereit steht.\n\nEs wartet ein Windreiter auf Euch, mit dem Ihr die aktuelle Karawanenlieferung einhol'n könnt.\n\n– Rokhan", sourceObjective = "Sprecht mit Steingardist Brox bei der Karawane in Nagrand.", completion = "Sie haben uns... wie aus dem Nichts... angegriffen.\n\n<Der Steinwächter verliert beinahe das Bewusstsein.>", sourceObjectiveStatus = "unverified-source-field" }
quests[36953] = { id = 36953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Sache der Strategie", description = "**Streng vertraulich – Kommandant {name}**\n\nDie Eiserne Horde ist ein würdiger Feind.\n\nSie haben ihre Flotte von Gorgrond nach Talador verlegt und meine Spione haben davon nix mitbekommen. Talador ist ein wichtiger Knotenpunkt für den ganzen Kontinent. Wir dürf'n ihnen den nicht überlassen.\n\nKeine Sorge, <Scheff/Scheffin>, wir kümmern uns drum. Vorarbeiter Grobash baut gerade jetzt einen Außenposten für unsere Truppen. Der wird bereit sein, sobald Ihr dort ankommt, Kommandant.\n\n– Rokhan", sourceObjective = "Sprecht mit Bron Himmelshorn, um Euren Flug nach Talador anzutreten.", completion = "Wie Ihr befehlt. Ich benötige Euren Rat, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[36955] = { id = 36955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Jäger und Gejagte", description = "Wir sind von Feinden umgeben und mit jedem neuen Tag, werden es mehr. Es ist an der Zeit, dass wir einen entschlossenen Schlag gegen ihre Armeen ausführen, Champion.\n\nUm mich herum seht Ihr Abbilder unserer meistgehassten Gegner. Ihr werdet sie zu Fall bringen, {name}. Ihr werdet zur Nemesis werden, und sie werden vor Angst fliehen, sobald sie Euch erblicken.\n\nWählt nun das Ziel Eurer Wut und verbrennt das Bildnis des Volkes, auf das Ihr es abgesehen habt. Sprecht erneut mit mir, wenn Ihr Eure Wahl getroffen habt.", sourceObjective = "Verbrennt ein Nemesisbildnis im Heiligtum des Gladiators und sprecht dann mit Kuros.", completion = "Eine letzte Warnung: Nachdem Ihr diese Wahl getroffen habt, könnt Ihr sie nicht rückgängig machen oder eine neue Wahl treffen, bevor Ihr Eure Mission abgeschlossen habt.\n\nWenn Ihr bei Eurer Wahl sicher seid, wird Euch auch der Sieg sicher sein.\n\nErfüllt die Herzen Eurer Widersacher mit Furcht! Ruhm der Allianz! Für Draenor!", sourceObjectiveStatus = "unverified-source-field" }
quests[36956] = { id = 36956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis Flag, Human" }
quests[36957] = { id = 36957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Zum Tod werden", description = "Ihr habt Eure Opfer ausgewählt, und sie werden sicherlich bald Euren gnadenlosen Zorn zu spüren bekommen, aber zunächst müsst Ihr in die Wildnis Draenors vordringen und in einem Kampf auf Leben und Tod einem Blutelf das noch schlagende Herz aus der Brust reißen. Kehrt mit Eurer Beute hierher zurück.\n\nDurch das Herz Eures Feindes werden sich die Geister mit Euren Sinnen verbinden und Euch das zweite Gesicht, sowie ein scharfes Gehör verleihen, damit Ihr Eure Beute verfolgen und Eure Überlegenheit deutlich machen könnt.", sourceObjective = "Tötet einen Blutelfenspielercharakter in PvP-Kämpfen in Draenor und beschafft dessen Blutelfenherz.", sourceObjectiveStatus = "unverified-source-field" }
quests[36958] = { id = 36958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Verhängnis der Sin'dorei", description = "<Kuros übergibt Euch das blutige Herz.>\n\nDas Ritual ist abgeschlossen. Euer Widersacher ist dem Tode geweiht.\n\nEure Arbeit, diese Welt vom Feind zu befreien, beginnt jetzt. Tötet alle Blutelfen, die sich trotzig der Allianz entgegenstellen. Möge ihr Tod als Warnung für den Rest der Horde dienen: Sie verlassen Draenor, oder sie werden sterben.\n\nKehrt zurück, wenn Ihr Euren Rachedurst mit dem Blut der Blutelfen gestillt habt.\n\nBesiegt Euren Feind und werdet als Verhängnis der Sin'dorei bekannt. Versagt, und Ihr werdet ein Nichts sein.", sourceObjective = "Tötet 500 Blutelfenspielercharaktere in PvP-Kämpfen in Draenor.", sourceObjectiveStatus = "unverified-source-field" }
quests[36959] = { id = 36959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Zum Tod werden", description = "Ihr habt Eure Opfer ausgewählt und sie werden sicherlich bald Euren gnadenlosen Zorn zu spüren bekommen, aber zunächst müsst Ihr in die Wildnis Draenors vordringen und in einem Kampf auf Leben und Tod einem Verlassenen das noch schlagende Herz aus der Brust reißen. Kehrt mit Eurer Beute hierher zurück.\n\nDurch das Herz Eures Feindes werden sich die Geister mit Euren Sinnen verbinden und Euch das zweite Gesicht, sowie ein scharfes Gehör verleihen, damit Ihr Eure Beute verfolgen und Eure Überlegenheit deutlich machen könnt.", sourceObjective = "Tötet einen Verlassenenspielercharakter in PvP-Kämpfen in Draenor und beschafft dessen Verlassenenherz.", progress = "Habt Ihr das Herz eines würdigen Feindes beschafft?", completion = "Mit diesem Herz könnt Ihr Dinge sehen und hören, wie es sonst nur die großen Geister können. Euer Feind wird nicht in der Lage sein, sich vor Euren unnachgiebigen Angriffen zu verstecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[36960] = { id = 36960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Totengräber", description = "<Kuros übergibt Euch das blutige Herz.>\n\nDas Ritual ist abgeschlossen. Euer Widersacher ist dem Tode geweiht.\n\nEure Arbeit, diese Welt vom Feind zu befreien, beginnt jetzt. Tötet alle Verlassenen, die sich trotzig der Allianz entgegenstellen. Möge Ihr Tod als Warnung für den Rest der Horde dienen: Sie verlassen Draenor, oder sie werden sterben.\n\nKehrt zurück, wenn Ihr Euren Rachedurst mit dem schwarzen Blut der Verlassenen gestillt habt.\n\nBesiegt Euren Feind und werdet als <Totengräber/Totengräberin> bekannt. Versagt, und Ihr werdet ein Nichts sein.", sourceObjective = "Tötet 500 Verlassenenspielercharaktere in PvP-Kämpfen in Draenor.", completion = "Die Wahrheit über Eure Taten steht in Euren Augen. Euer Hunger nach dem Feind wurde gestillt mit Rufen nach Gnade und Strömen von Blut.\n\nNehmt Euren Platz als Totengräberin ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[36961] = { id = 36961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Zum Tod werden", description = "Ihr habt Eure Opfer ausgewählt, und sie werden sicherlich bald Euren gnadenlosen Zorn zu spüren bekommen, aber zunächst müsst Ihr in die Wildnis Draenors vordringen und in einem Kampf auf Leben und Tod einem Tauren das noch schlagende Herz aus der Brust reißen. Kehrt mit Eurer Beute hierher zurück.\n\nDurch das Herz Eures Feindes werden sich die Geister mit Euren Sinnen verbinden und Euch das zweite Gesicht, sowie ein scharfes Gehör verleihen, damit Ihr Eure Beute verfolgen und Eure Überlegenheit deutlich machen könnt.", sourceObjective = "Tötet einen Taurenspielercharakter in PvP-Kämpfen in Draenor und beschafft dessen Taurenherz.", sourceObjectiveStatus = "unverified-source-field" }
quests[36962] = { id = 36962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Der Fleischer", description = "<Kuros übergibt Euch das blutige Herz.>\n\nDas Ritual ist abgeschlossen. Euer Widersacher ist dem Tode geweiht.\n\nEure Arbeit, diese Welt vom Feind zu befreien, beginnt jetzt. Tötet alle Tauren, die sich trotzig der Allianz entgegenstellen. Möge Ihr Tod als Warnung für den Rest der Horde dienen: Sie verlassen Draenor, oder sie werden sterben.\n\nKehrt zurück, wenn Ihr Euren Rachedurst mit dem Blut der Tauren gestillt habt.\n\nBesiegt Euren Feind und werdet als <Fleischer/Fleischerin> bekannt. Versagt, und Ihr werdet ein Nichts sein.", sourceObjective = "Tötet 500 Taurenspielercharaktere in PvP-Kämpfen in Draenor.", sourceObjectiveStatus = "unverified-source-field" }
quests[36963] = { id = 36963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Zum Tod werden", description = "Ihr habt Eure Opfer ausgewählt, und sie werden sicherlich bald Euren gnadenlosen Zorn zu spüren bekommen, aber zunächst müsst Ihr in die Wildnis Draenors vordringen und in einem Kampf auf Leben und Tod einem Orc das noch schlagende Herz aus der Brust reißen. Kehrt mit Eurer Beute hierher zurück.\n\nDurch das Herz Eures Feindes werden sich die Geister mit Euren Sinnen verbinden und Euch das zweite Gesicht, sowie ein scharfes Gehör verleihen, damit Ihr Eure Beute verfolgen und Eure Überlegenheit deutlich machen könnt.", sourceObjective = "Tötet einen Orcspielercharakter in PvP-Kämpfen in Draenor und beschafft dessen Orcherz.", progress = "Habt Ihr das Herz eines würdigen Feindes beschafft?", completion = "Mit diesem Herz könnt Ihr Dinge sehen und hören, wie es sonst nur die großen Geister können. Euer Feind wird nicht in der Lage sein, sich vor Euren unnachgiebigen Angriffen zu verstecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[36964] = { id = 36964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Orctöter", description = "<Kuros übergibt Euch das blutige Herz.>\n\nDas Ritual ist abgeschlossen. Euer Widersacher ist dem Tode geweiht.\n\nEure Arbeit, diese Welt vom Feind zu befreien, beginnt jetzt. Tötet alle Orcs, die sich trotzig der Allianz entgegenstellen. Möge Ihr Tod als Warnung für den Rest der Horde dienen: Sie verlassen Draenor, oder sie werden sterben.\n\nKehrt zurück, wenn Ihr Euren Rachedurst mit dem Blut der Orcs gestillt habt.\n\nBesiegt Euren Feind und werdet als <Orctöter/Orctöterin> bekannt. Versagt, und Ihr werdet ein Nichts sein.", sourceObjective = "Tötet 500 Orcspielercharaktere in PvP-Kämpfen in Draenor.", completion = "Die Wahrheit über Eure Taten steht in Euren Augen. Euer Hunger nach dem Feind wurde gestillt mit Rufen nach Gnade und Strömen von Blut.\n\nNehmt Euren Platz als Orctöterin ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[36965] = { id = 36965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Zum Tod werden", description = "Ihr habt Eure Opfer ausgewählt, und sie werden sicherlich bald Euren gnadenlosen Zorn zu spüren bekommen, aber zunächst müsst Ihr in die Wildnis Draenors vordringen und in einem Kampf auf Leben und Tod einem Troll das noch schlagende Herz aus der Brust reißen. Kehrt mit Eurer Beute hierher zurück.\n\nDurch das Herz Eures Feindes werden sich die Geister mit Euren Sinnen verbinden und Euch das zweite Gesicht, sowie ein scharfes Gehör verleihen, damit Ihr Eure Beute verfolgen und Eure Überlegenheit deutlich machen könnt.", sourceObjective = "Tötet einen Trollspielercharakter in PvP-Kämpfen in Draenor und beschafft dessen Trollherz.", progress = "Habt Ihr das Herz eines würdigen Feindes beschafft?", completion = "Mit diesem Herz könnt Ihr Dinge sehen und hören, wie es sonst nur die großen Geister können. Euer Feind wird nicht in der Lage sein, sich vor Euren unnachgiebigen Angriffen zu verstecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[36966] = { id = 36966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Trolljäger", description = "<Kuros übergibt Euch das blutige Herz.>\n\nDas Ritual ist abgeschlossen. Euer Widersacher ist dem Tode geweiht.\n\nEure Arbeit, diese Welt vom Feind zu befreien, beginnt jetzt. Tötet alle Trolle, die sich trotzig der Allianz entgegenstellen. Möge Ihr Tod als Warnung für den Rest der Horde dienen: Sie verlassen Draenor, oder sie werden sterben.\n\nKehrt zurück, wenn Ihr Euren Rachedurst mit dem Blut der Trolle gestillt habt.\n\nBesiegt Euren Feind und werdet als <Trolljäger/Trolljägerin> bekannt. Versagt, und Ihr werdet ein Nichts sein.", sourceObjective = "Tötet 500 Trollspielercharaktere in PvP-Kämpfen in Draenor.", sourceObjectiveStatus = "unverified-source-field" }
quests[36967] = { id = 36967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Zum Tod werden", description = "Ihr habt Eure Opfer ausgewählt, und sie werden sicherlich bald Euren gnadenlosen Zorn zu spüren bekommen, aber zunächst müsst Ihr in die Wildnis Draenors vordringen und in einem Kampf auf Leben und Tod einem Pandaren das noch schlagende Herz aus der Brust reißen. Kehrt mit Eurer Beute hierher zurück.\n\nDurch das Herz Eures Feindes werden sich die Geister mit Euren Sinnen verbinden und Euch das zweite Gesicht, sowie ein scharfes Gehör verleihen, damit Ihr Eure Beute verfolgen und Eure Überlegenheit deutlich machen könnt.", sourceObjective = "Tötet einen Pandarenspielercharakter in PvP-Kämpfen in Draenor und beschafft dessen Pandarenherz.", sourceObjectiveStatus = "unverified-source-field" }
quests[36968] = { id = 36968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Huojins Untergang", description = "<Kuros übergibt Euch das blutige Herz.>\n\nDas Ritual ist abgeschlossen. Euer Widersacher ist dem Tode geweiht.\n\nEure Arbeit, diese Welt vom Feind zu befreien, beginnt jetzt. Tötet alle Pandaren, die sich trotzig der Allianz entgegenstellen. Möge Ihr Tod als Warnung für den Rest der Horde dienen: Sie verlassen Draenor, oder sie werden sterben.\n\nKehrt zurück, wenn Ihr Euren Rachedurst mit dem Blut der Pandaren gestillt habt.\n\nBesiegt Euren Feind und werdet als Huojins Untergang bekannt. Versagt, und Ihr werdet ein Nichts sein.", sourceObjective = "Tötet 500 Pandarenspielercharaktere in PvP-Kämpfen in Draenor.", sourceObjectiveStatus = "unverified-source-field" }
quests[36969] = { id = 36969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Zum Tod werden", description = "Ihr habt Eure Opfer ausgewählt, und sie werden sicherlich bald Euren gnadenlosen Zorn zu spüren bekommen, aber zunächst müsst Ihr in die Wildnis Draenors vordringen und in einem Kampf auf Leben und Tod einem Goblin das noch schlagende Herz aus der Brust reißen. Kehrt mit Eurer Beute hierher zurück.\n\nDurch das Herz Eures Feindes werden sich die Geister mit Euren Sinnen verbinden und Euch das zweite Gesicht, sowie ein scharfes Gehör verleihen, damit Ihr Eure Beute verfolgen und Eure Überlegenheit deutlich machen könnt.", sourceObjective = "Tötet einen Goblinspielercharakter in PvP-Kämpfen in Draenor und beschafft dessen Goblinherz.", sourceObjectiveStatus = "unverified-source-field" }
quests[36970] = { id = 36970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Schlächter von Kezan", description = "<Kuros übergibt Euch das blutige Herz.>\n\nDas Ritual ist abgeschlossen. Euer Widersacher ist dem Tode geweiht.\n\nEure Arbeit, diese Welt vom Feind zu befreien, beginnt jetzt. Tötet alle Goblins, die sich trotzig der Allianz entgegenstellen. Möge Ihr Tod als Warnung für den Rest der Horde dienen: Sie verlassen Draenor, oder sie werden sterben.\n\nKehrt zurück, wenn Ihr Euren Rachedurst mit dem Blut der Goblins gestillt habt.\n\nBesiegt Euren Feind und werdet als <Schlächter/Schlächterin> von Kezan bekannt. Versagt, und Ihr werdet ein Nichts sein.", sourceObjective = "Tötet 500 Goblinspielercharaktere in PvP-Kämpfen in Draenor.", sourceObjectiveStatus = "unverified-source-field" }
quests[36971] = { id = 36971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbukausbildung: Riesenhauer", description = "Der erste Schritt bei der Ausbildung Eures Reittieres für den Krieg ist es, das Tier an den Anblick und die Geräusche des Gefechtes zu gewöhnen. Wenn es keine vernünftige Ausbildung genossen hat, könnte es sich sonst erschrecken und davonlaufen.\n\nReitet mit diesem kleinen Talbuk zu den Ebenen des Schattenmondtals und kämpft zusammen gegen die größte Bestie, die Ihr finden könnt. Das ist förderlich für sein Selbstbewusstsein!", sourceObjective = "Besiegt Riesenhauer vom Rücken Eures Ausbildungstalbuks aus.", completion = "Das sollte ihm guttun. Wir werden ihn heute Abend etwas ruhen lassen und morgen dann größere Ziele ins Visier nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36972] = { id = 36972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbukausbildung: Rakkiri", description = "Jetzt, wo Euer Talbuk schon über etwas Kampferfahrung verfügt, wollen wir ihn mal in ihm unvertrauten Gegenden testen.\n\nDie eisige Bergwelt des Frostfeuergrats sollte ein guter Test sein. Sucht dort nach einer großen, bösartigen Bestie und schaltet sie mit Eurem Talbuk aus.", sourceObjective = "Besiegt Rakkiri vom Rücken Eures Ausbildungstalbuks aus.", completion = "Hey! Der Talbuk hat sich wahrlich wacker geschlagen! Gönnen wir ihm etwas Ruhe!", sourceObjectiveStatus = "unverified-source-field" }
quests[36973] = { id = 36973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbukausbildung: Sichelklaue", description = "Schon viele Reittiere sind beim Anblick eines gefährlichen Raubtieres geflüchtet. Und im Gebiet der abgeschiedenen Klippen von Gorgrond leben ein paar der gefährlichsten von ihnen.\n\nWir wollen Euren Talbuk auf eine harte Probe stellen. Mal sehen, ob Ihr beide den mächtigen Raptor Sichelklaue ausschalten könnt.", sourceObjective = "Besiegt Sichelklaue vom Rücken Eures Ausbildungstalbuks aus.", completion = "Das waren ein paar gewaltige Klauen, gegen die Ihr da kämpfen musstet. Euer Talbuk braucht nach diesem Gemetzel ein Schläfchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36974] = { id = 36974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbukausbildung: Gezz'ran", description = "Da draußen in der Wildnis gibt es noch jede Menge weiterer Bestien, die Euer Tier zum Frühstück verspeisen könnten. Einer der gerissensten Jäger in Draenor ist der Pirscher.\n\nPirscher können sich ihrer Umgebung anpassen und sich so anschleichen und die Eier ihrer Beute stehlen. Versucht einmal, ob Ihr diesen natürlichen Verteidigungsmechanismus mit Eurem Talbuk überwinden könnt. In Talador gibt es ein paar ausgesprochen bösartige Pirscher.", sourceObjective = "Besiegt Gezz'ran vom Rücken Eures Ausbildungstalbuks aus.", completion = "Ihr habt es geschafft! Ich wette, Eurem Talbuk gefallen diese Zweikämpfe. Wir werden ihn jetzt etwas ruhen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36975] = { id = 36975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbukausbildung: Bulbapore", description = "Weit unten im Süden, bei den Spitzen von Arak, ist das Land von Pilzen überschwemmt worden, die unter Wasser wachsen. Und das Resultat? In dem gesamten Gebiet schießen überall pilzartige Kreaturen aus dem Boden.\n\nIndem Ihr den Kampf mit einer solch seltsamen Spezies wie dem Fungusgiganten Bulbapore aufnehmt, könnt Ihr testen, wie Euer Talbuk auf Gegner reagiert, die er noch nicht kennt.", sourceObjective = "Besiegt Bulbapore vom Rücken Eures Ausbildungstalbuks aus.", completion = "Das war sicherlich ein prächtiger Kampf! Gut gemacht! Gönnen wir dem Tier für heute etwas Ruhe.", sourceObjectiveStatus = "unverified-source-field" }
quests[36976] = { id = 36976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbukausbildung: Grausame Oger", description = "In Nagrand sind die mächtigsten Wildtiere Draenors beheimatet. Und die Oger in dieser Gegend haben gelernt, diese Tiere mithilfe brutaler Techniken zu zähmen.\n\nEs gibt einen bestimmten Oger, der gorianische Tierpeitscher, der besonders stark nach Angst und Blut riecht. Nehmt es mit ihm auf, um zu sehen, wie Euer Talbuk auf ihn reagiert.", sourceObjective = "Besiegt den gorianischen Tierpeitscher vom Rücken Eures Ausbildungstalbuks aus.", completion = "Diese armen Tiere! Ich bin froh, dass Ihr diesen Oger aus dem Verkehr gezogen habt. Kommt morgen wieder, damit wir mit der Ausbildung fortfahren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[36977] = { id = 36977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbukausbildung: Nachtflügelwindroc", description = "Die Windrocs von Nagrand sind gerissene Jäger, die oftmals im Schwarm auf unaufmerksame Beute niederstoßen. Wenn Euer Tier nicht lernt, auch den Luftraum im Auge zu behalten, wird es schon bald kein Auge mehr haben.\n\nMacht Euch auf nach Nagrand und nehmt es mit dem stärksten Windroc auf, dem Nachtflügelwindroc. Das sollte eine würdige Prüfung für Euch beide sein.", sourceObjective = "Besiegt den Nachtflügelwindroc vom Rücken Eures Ausbildungstalbuks aus.", completion = "Von jetzt an wird Euer Reittier ganz sicher daran denken, den Himmel im Auge zu behalten. Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[36978] = { id = 36978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbukausbildung: Zornmotte", description = "Tief in den Wäldern von Nagrand leben ein paar Tiere, die selbst den gefährlichsten Raubtieren entkommen können. Das größte dieser Tiere ist die Zornmotte. Sie ist mit einem übel riechenden Staub bedeckt.\n\nWenn dieser Mottenstaub sogar Wölfe abschrecken kann, wird dies ein guter Test für Euren Talbuk. Ihr müsst dafür sorgen, dass er sich nicht davon ablenken lässt, wenn Ihr die Motte zur Strecke bringen wollt.", sourceObjective = "Besiegt die Zornmotte vom Rücken Eures Ausbildungstalbuks aus.", completion = "Schön, dass Ihr zurück seid. Es wird eine Weile dauern, diesen Staub wieder loszuwerden.", sourceObjectiveStatus = "unverified-source-field" }
quests[36979] = { id = 36979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbukausbildung: Donnersturm", description = "Die Naturgewalten stellen für einige Tiere oftmals ein Problem dar. Habt Ihr schon mal einen Widder bei Unwetter beobachtet? Sie verstecken sich hinter allem, was größer ist als sie selbst. Vielleicht glauben sie, dass die Welt untergeht. Auf jeden Fall ist es nicht angenehm, wenn man in diesem Moment auf ihrem Rücken sitzt.\n\nIn Nagrand, auf einem windumpeitschten Kliff hoch über der Küste, lebt eine Kreatur, die aus reinem Unwetter besteht. Schwingt Euch auf den Rücken Eures Talbuks, um Donnersturm auszuschalten. Dann werden wir ja erleben, ob sich Euer Tier verunsichern lässt.", sourceObjective = "Besiegt Donnersturm vom Rücken Eures Ausbildungstalbuks aus.", completion = "Nun, er ist ein bisschen nass, aber ansonsten ganz vergnügt. Ich werde ihn trocknen und dann zu Bett bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36980] = { id = 36980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbukausbildung: Eisenfräser", description = "So, wir haben bisher gegen Feinde in der Luft, an Land und sogar im Unwetter gekämpft. Aber was passiert, wenn sich die Kreaturen unter unseren Füßen befinden? Wir werden es bald herausfinden!\n\nDer Felswurm ist ein gerissener Jäger, der seine Beute aus dem sandigen Untergrund heraus angreift. Viele Tiere Nagrands werden daher durch Erschütterungen der Erde erschreckt. Reitet mit Eurem Talbuk zu den sandigen Gestaden und versucht, einen der älteren Felswürmer auszuschalten: Eisenfräser.", sourceObjective = "Besiegt Eisenfräser vom Rücken Eures Ausbildungstalbuks aus.", completion = "Der Sandwurm ist Geschichte? Gut gemacht. Ich werde das Tier jetzt für Euch schlafen legen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36981] = { id = 36981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbukausbildung: Orcjäger", description = "In den Reihen des Kriegshymnenklans in Nagrand gibt es einige der besten Jäger, die ich leider jemals treffen musste. Wenn es einen ernsthaften Test für Euer zukünftiges Reittier gibt, dann ist es einer ihrer Bestientöter.\n\nDa draußen in Nagrand gibt es einen Orc namens Karak. Sie nennen ihn den \"Großjäger\", denn er hat mehr wilde Bestien erlegt als alle anderen seines Klans. Schwingt Euch auf Euren Talbuk und schaltet ihn aus. Im Namen aller armen, geschändeten Kreaturen!", sourceObjective = "Besiegt Karak den Großjäger vom Rücken Eures Ausbildungstalbuks aus.", completion = "Der Jäger wurde also zum Gejagten, wie? Euer Tier scheint auch alles unbeschadet überstanden zu haben. Ich werde es abbürsten.", sourceObjectiveStatus = "unverified-source-field" }
quests[36982] = { id = 36982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbukausbildung: Der Garn", description = "Ich habe eine letzte Herausforderung für Euch, Kommandant. Und das wird kein Zuckerschlecken.\n\nMan nennt sie die \"Garn\". Diese nachtschwarzen Wölfe sind doppelt so groß wie normale Wölfe und können einen Mann in Sekundenschnelle in Stücke reißen. Jedes Tier, das noch bei Verstand ist, hat panische Angst vor einem solchen Raubtier.\n\nDa draußen streift ein einsamer Garn umher, der den ganzen Weg von seiner Heimat im Frostfeuergrat bis nach Nagrand gewandert ist. Schwingt Euch auf Euren Talbuk und schaltet ihn aus. Wenn Ihr beide überlebt, wird Euer Talbuk wahrhaft für den Krieg bereit sein.", sourceObjective = "Besiegt Malmkiefer vom Rücken Eures Ausbildungstalbuks aus.", completion = "Dank Eurer Ausdauer und Mühen ist dieser Talbuk von einem Silberpelzchen zu einer echten Kriegsbestie herangewachsen.\n\nIch freue mich, Euch hiermit die Zügel dieses vollständig ausgebildeten Reittieres übergeben zu können, Kommandant. Reitet es mit Stolz!", sourceObjectiveStatus = "unverified-source-field" }
quests[36983] = { id = 36983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grollhufausbildung: Riesenhauer", description = "Der erste Schritt bei der Ausbildung Eures Reittieres für den Krieg ist es, das Tier an den Anblick und die Geräusche des Gefechtes zu gewöhnen. Wenn es keine vernünftige Ausbildung genossen hat, könnte es sich sonst erschrecken und davonlaufen.\n\nReitet mit diesem kleinen Grollhuf zu den Ebenen des Schattenmondtals und kämpft zusammen gegen die größte Bestie, die Ihr finden könnt. Das ist förderlich für sein Selbstbewusstsein!", sourceObjective = "Besiegt Riesenhauer vom Rücken Eures Ausbildungsgrollhufs aus.", completion = "Das sollte ihm guttun. Wir werden ihn heute Abend etwas ruhen lassen und morgen dann größere Ziele ins Visier nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36984] = { id = 36984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grollhufausbildung: Rakkiri", description = "Jetzt, wo Euer Grollhuf schon über etwas Kampferfahrung verfügt, wollen wir ihn mal in unwirtlicheren Gegenden testen.\n\nReitet mit Eurem Grollhuf in die eisige Bergwelt des Frostfeuergrats und stellt Euch dem Kampf mit einem prächtigen Raubtier: Rakkiri. Jetzt wird sich Euer Reittier beweisen müssen.", sourceObjective = "Besiegt Rakkiri vom Rücken Eures Ausbildungsgrollhufs aus.", completion = "Hey! Der Grollhuf hat sich wahrlich wacker geschlagen! Gönnen wir ihm etwas Ruhe!", sourceObjectiveStatus = "unverified-source-field" }
quests[36985] = { id = 36985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grollhufausbildung: Sichelklaue", description = "Schon viele Reittiere sind beim Anblick eines gefährlichen Raubtieres geflüchtet. Und im Gebiet der abgeschiedenen Klippen von Gorgrond leben ein paar der gefährlichsten von ihnen.\n\nWir wollen Euren Grollhuf auf eine harte Probe stellen. Mal sehen, ob Ihr beide den mächtigen Raptor Sichelklaue ausschalten könnt.", sourceObjective = "Besiegt Sichelklaue vom Rücken Eures Ausbildungsgrollhufs aus.", completion = "Das waren ein paar gewaltige Klauen, gegen die Ihr da kämpfen musstet. Euer Grollhuf braucht nach diesem Gemetzel ein Schläfchen.", sourceObjectiveStatus = "unverified-source-field" }
