quests[36987] = { id = 36987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grollhufausbildung: Bulbapore", description = "Weit unten im Süden, bei den Spitzen von Arak, ist das Land von Pilzen überschwemmt worden, die unter Wasser wachsen. Und das Resultat? In dem gesamten Gebiet schießen überall pilzartige Kreaturen aus dem Boden.\n\nIndem Ihr den Kampf mit einer solch seltsamen Spezies wie dem Fungusgiganten Bulbapore aufnehmt, könnt Ihr testen, wie Euer Grollhuf auf Gegner reagiert, die er noch nicht kennt.", sourceObjective = "Besiegt Bulbapore vom Rücken Eures Ausbildungsgrollhufs aus.", completion = "Das war sicherlich ein prächtiger Kampf! Gut gemacht! Gönnen wir dem Tier für heute etwas Ruhe.", sourceObjectiveStatus = "unverified-source-field" }
quests[36988] = { id = 36988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grollhufausbildung: Grausame Oger", description = "In Nagrand sind die mächtigsten Wildtiere Draenors beheimatet. Und die Oger in dieser Gegend haben gelernt, diese Tiere mithilfe brutaler Techniken zu zähmen.\n\nEs gibt einen bestimmten Oger, der gorianische Tierpeitscher, der besonders stark nach Angst und Blut riecht. Nehmt es mit ihm auf, um zu sehen, wie Euer Grollhuf auf ihn reagiert.", sourceObjective = "Besiegt den gorianischen Tierpeitscher vom Rücken Eures Ausbildungsgrollhufs aus.", completion = "Diese armen Tiere! Ich bin froh, dass Ihr diesen Oger aus dem Verkehr gezogen habt. Kommt morgen wieder, damit wir mit der Ausbildung fortfahren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[36989] = { id = 36989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grollhufausbildung: Nachtflügelwindroc", description = "Die Windrocs von Nagrand sind gerissene Jäger, die oftmals im Schwarm auf unaufmerksame Beute niederstoßen. Wenn Euer Tier nicht lernt, auch den Luftraum im Auge zu behalten, wird es schon bald kein Auge mehr haben.\n\nMacht Euch auf nach Nagrand und nehmt es mit dem stärksten Windroc auf, dem Nachtflügelwindroc. Das sollte eine würdige Prüfung für Euch beide sein.", sourceObjective = "Besiegt den Nachtflügelwindroc vom Rücken Eures Ausbildungsgrollhufs aus.", completion = "Von jetzt an wird Euer Reittier ganz sicher daran denken, den Himmel im Auge zu behalten. Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[36990] = { id = 36990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grollhufausbildung: Zornmotte", description = "Tief in den Wäldern von Nagrand leben ein paar Tiere, die selbst den gefährlichsten Raubtieren entkommen können. Das größte dieser Tiere ist die Zornmotte. Sie ist mit einem übel riechenden Staub bedeckt.\n\nWenn dieser Mottenstaub sogar Wölfe abschrecken kann, wird dies ein guter Test für Euren Grollhuf. Ihr müsst dafür sorgen, dass er sich nicht davon ablenken lässt, wenn Ihr die Motte zur Strecke bringen wollt.", sourceObjective = "Besiegt die Zornmotte vom Rücken Eures Ausbildungsgrollhufs aus.", completion = "Schön, dass Ihr zurück seid. Es wird eine Weile dauern, diesen Staub wieder loszuwerden.", sourceObjectiveStatus = "unverified-source-field" }
quests[36991] = { id = 36991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grollhufausbildung: Donnersturm", description = "Die Naturgewalten stellen für einige Tiere oftmals ein Problem dar. Habt Ihr schon mal einen Widder bei Unwetter beobachtet? Sie verstecken sich hinter allem, was größer ist als sie selbst. Vielleicht glauben sie, dass die Welt untergeht. Auf jeden Fall ist es nicht angenehm, wenn man in diesem Moment auf ihrem Rücken sitzt.\n\nIn Nagrand, auf einem windumpeitschten Kliff hoch über der Küste, lebt eine Kreatur, die aus reinem Unwetter besteht. Schwingt Euch auf den Rücken Eures Grollhufs, um Donnersturm auszuschalten. Dann werden wir ja erleben, ob sich Euer Tier verunsichern lässt.", sourceObjective = "Besiegt Donnersturm vom Rücken Eures Ausbildungsgrollhufs aus.", completion = "Nun, er ist ein bisschen nass, aber ansonsten ganz vergnügt. Ich werde ihn trocknen und dann zu Bett bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36992] = { id = 36992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grollhufausbildung: Eisenfräser", description = "So, wir haben bisher gegen Feinde in der Luft, an Land und sogar im Unwetter gekämpft. Aber was passiert, wenn sich die Kreaturen unter unseren Füßen befinden? Wir werden es bald herausfinden!\n\nDer Felswurm ist ein gerissener Jäger, der seine Beute aus dem sandigen Untergrund heraus angreift. Viele Tiere Nagrands werden daher durch Erschütterungen der Erde erschreckt. Reitet mit Eurem Grollhuf zu den sandigen Gestaden und versucht, einen der älteren Felswürmer auszuschalten: Eisenfräser.", sourceObjective = "Besiegt Eisenfräser vom Rücken Eures Ausbildungsgrollhufs aus.", completion = "Der Sandwurm ist Geschichte? Gut gemacht. Ich werde das Tier jetzt für Euch schlafen legen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36993] = { id = 36993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eberausbildung: Orcjäger", description = "In den Reihen des Kriegshymnenklans in Nagrand gibt es einige der besten Jäger, die ich leider jemals treffen musste. Wenn es einen ernsthaften Test für Euer zukünftiges Reittier gibt, dann ist es einer ihrer Bestientöter.\n\nDa draußen in Nagrand gibt es einen Orc namens Karak. Sie nennen ihn den \"Großjäger\", denn er hat mehr wilde Bestien erlegt als alle anderen seines Klans. Schwingt Euch auf Euren Grollhuf und schaltet ihn aus. Im Namen aller armen, geschändeten Kreaturen!", sourceObjective = "Besiegt Karak den Großjäger vom Rücken Eures Ausbildungsgrollhufs aus.", completion = "Der Jäger wurde also zum Gejagten, wie? Euer Tier scheint auch alles unbeschadet überstanden zu haben. Ich werde es abbürsten.", sourceObjectiveStatus = "unverified-source-field" }
quests[36994] = { id = 36994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grollhufausbildung: Der Garn", description = "Ich habe eine letzte Herausforderung für Euch, Kommandant. Und das wird kein Zuckerschlecken.\n\nMan nennt sie die \"Garn\". Diese nachtschwarzen Wölfe sind doppelt so groß wie normale Wölfe und können einen Mann in Sekundenschnelle in Stücke reißen. Jedes Tier, das noch bei Verstand ist, hat panische Angst vor einem solchen Raubtier.\n\nDa draußen streift ein einsamer Garn umher, der den ganzen Weg von seiner Heimat im Frostfeuergrat bis nach Nagrand gewandert ist. Schwingt Euch auf Euren Grollhuf und schaltet ihn aus. Wenn Ihr beide überlebt, wird Euer Grollhuf für alle zukünftigen Aufgaben wahrhaft bereit sein.", sourceObjective = "Besiegt Malmkiefer vom Rücken Eures Ausbildungsgrollhufs aus.", completion = "Dank Eurer großartigen Leistung hat Euer Grollhuf die Ausbildung erfolgreich bestanden! Mir bleibt jetzt nur noch, Euch die Zügel in die Hand zu drücken und Euch auf den Weg zu schicken. Gut gemacht, Kommandant!", sourceObjectiveStatus = "unverified-source-field" }
quests[36995] = { id = 36995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eberausbildung: Sichelklaue", description = "Der Eber hat schon einige Kämpfe in Gorgrond erlebt. Das sollte es etwas einfacher machen, ihn auszubilden. Wir starten auf bekanntem Territorium, genau wie mit den anderen Tieren.\n\nMacht Euch gemeinsam auf, um den riesigen Raptor Sichelklaue auszuschalten.", sourceObjective = "Besiegt Sichelklaue vom Rücken Eures Ausbildungsebers aus.", completion = "Das waren ein paar gewaltige Klauen, gegen die Ihr da kämpfen musstet. Euer Eber braucht nach diesem Gemetzel ein Schläfchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36996] = { id = 36996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eberausbildung: Gezz'ran", description = "Da draußen in der Wildnis gibt es noch jede Menge weiterer Bestien, die Euer Tier zum Frühstück verspeisen könnten. Einer der gerissensten Jäger in Draenor ist der Pirscher.\n\nPirscher können sich ihrer Umgebung anpassen und sich so anschleichen und die Eier ihrer Beute stehlen. Versucht einmal, ob Ihr diesen natürlichen Verteidigungsmechanismus mit Eurem Eber überwinden könnt. In Talador gibt es ein paar ausgesprochen bösartige Pirscher.", sourceObjective = "Besiegt Gezz'ran vom Rücken Eures Ausbildungsebers aus.", completion = "Ihr habt es geschafft! Ich wette, Eurem Eber gefallen diese Zweikämpfe. Wir werden ihn jetzt etwas ruhen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36997] = { id = 36997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eberausbildung: Bulbapore", description = "Weit unten im Süden, bei den Spitzen von Arak, ist das Land von Pilzen überschwemmt worden, die unter Wasser wachsen. Und das Resultat? In dem gesamten Gebiet schießen überall pilzartige Kreaturen aus dem Boden.\n\nIndem Ihr den Kampf mit einer solch seltsamen Spezies wie dem Fungusgiganten Bulbapore aufnehmt, könnt Ihr testen, wie Euer Eber auf Gegner reagiert, die er noch nicht kennt.", sourceObjective = "Besiegt Bulbapore vom Rücken Eures Ausbildungsebers aus.", completion = "Das war sicherlich ein prächtiger Kampf! Gut gemacht! Gönnen wir dem Tier für heute etwas Ruhe.", sourceObjectiveStatus = "unverified-source-field" }
quests[36998] = { id = 36998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eberausbildung: Grausame Oger", description = "In Nagrand sind die mächtigsten Wildtiere Draenors beheimatet. Und die Oger in dieser Gegend haben gelernt, diese Tiere mithilfe brutaler Techniken zu zähmen.\n\nEs gibt einen bestimmten Oger, der gorianische Tierpeitscher, der besonders stark nach Angst und Blut riecht. Nehmt es mit ihm auf, um zu sehen, wie Euer Eber auf ihn reagiert.", sourceObjective = "Besiegt den gorianischen Tierpeitscher vom Rücken Eures Ausbildungsebers aus.", completion = "Diese armen Tiere! Ich bin froh, dass Ihr diesen Oger aus dem Verkehr gezogen habt. Kommt morgen wieder, damit wir mit der Ausbildung fortfahren können.", sourceObjectiveStatus = "unverified-source-field" }
