quests[37004] = { id = 37004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eberausbildung: Der Garn", description = "Ich habe eine letzte Herausforderung für Euch, Kommandant. Und das wird kein Zuckerschlecken.\n\nMan nennt sie die \"Garn\". Diese nachtschwarzen Wölfe sind doppelt so groß wie normale Wölfe und können einen Mann in Sekundenschnelle in Stücke reißen. Jedes Tier, das noch bei Verstand ist, hat panische Angst vor einem solchen Raubtier.\n\nDa draußen streift ein einsamer Garn umher, der den ganzen Weg von seiner Heimat im Frostfeuergrat bis nach Nagrand gewandert ist. Schwingt Euch auf Euren Eber und schaltet ihn aus. Wenn Ihr beide überlebt, wird Euer Eber für alle zukünftigen Aufgaben wahrhaft bereit sein.", sourceObjective = "Besiegt Malmkiefer vom Rücken Eures Ausbildungsebers aus.", completion = "Euer Felshauer ist jetzt bereit für den Kampf, Kommandant. Hier sind die Zügel. Ihr werdet sie brauchen, um dieses Muskelpaket zu reiten.\n\nIhr habt hervorragende Arbeit bei der Ausbildung geleistet!", sourceObjectiveStatus = "unverified-source-field" }
quests[37005] = { id = 37005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flussbestienausbildung: Gezz'ran", description = "Dieses Tier hat einige Jahre in der Wildnis von Talador verbracht. Deswegen denke ich, dass wir dort mit der Ausbildung beginnen sollten. Es ist bereits einigermaßen zahm, also wird die Ausbildung wohl nicht so lange dauern wie bei den anderen.\n\nIhr wisst ja sicherlich, dass Pirscher sich ihrer Umgebung anpassen und sich so anschleichen und die Eier ihrer Beute stehlen können. Versucht einmal, ob Ihr diesen natürlichen Verteidigungsmechanismus mit Eurer Flussbestie überwinden könnt.", sourceObjective = "Besiegt Gezz'ran vom Rücken Eurer Ausbildungsflussbestie aus.", completion = "Ihr habt es geschafft! Ich wette, Eurer Flussbestie gefallen diese Zweikämpfe. Wir werden sie jetzt etwas ruhen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37006] = { id = 37006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flussbestienausbildung: Bulbapore", description = "Weit unten im Süden, bei den Spitzen von Arak, ist das Land von Pilzen überschwemmt worden, die unter Wasser wachsen. Und das Resultat? In dem gesamten Gebiet schießen überall pilzartige Kreaturen aus dem Boden.\n\nIndem Ihr den Kampf mit einer solch seltsamen Spezies wie dem Fungusgiganten Bulbapore aufnehmt, könnt Ihr testen, wie Eure Flussbestie auf Gegner reagiert, die sie noch nicht kennt.", sourceObjective = "Besiegt Bulbapore vom Rücken Eurer Ausbildungsflussbestie aus.", completion = "Das war sicherlich ein prächtiger Kampf! Gut gemacht! Gönnen wir dem Tier für heute etwas Ruhe.", sourceObjectiveStatus = "unverified-source-field" }
quests[37007] = { id = 37007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flussbestienausbildung: Grausame Oger", description = "In Nagrand sind die mächtigsten Wildtiere Draenors beheimatet. Und die Oger in dieser Gegend haben gelernt, diese Tiere mithilfe brutaler Techniken zu zähmen.\n\nEs gibt einen bestimmten Oger, der gorianische Tierpeitscher, der besonders stark nach Angst und Blut riecht. Nehmt es mit ihm auf, um zu sehen, wie Eure Flussbestie auf ihn reagiert.", sourceObjective = "Besiegt den gorianischen Tierpeitscher vom Rücken Eurer Ausbildungsflussbestie aus.", completion = "Diese armen Tiere! Ich bin froh, dass Ihr diesen Oger aus dem Verkehr gezogen habt. Kommt morgen wieder, damit wir mit der Ausbildung fortfahren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[37008] = { id = 37008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flussbestienausbildung: Nachtflügelwindroc", description = "Die Windrocs von Nagrand sind gerissene Jäger, die oftmals im Schwarm auf unaufmerksame Beute niederstoßen. Wenn Euer Tier nicht lernt, auch den Luftraum im Auge zu behalten, wird es schon bald kein Auge mehr haben.\n\nMacht Euch auf nach Nagrand und nehmt es mit dem stärksten Windroc auf, dem Nachtflügelwindroc. Das sollte eine würdige Prüfung für Euch beide sein.", sourceObjective = "Besiegt den Nachtflügelwindroc vom Rücken Eurer Ausbildungsflussbestie aus.", completion = "Von jetzt an wird Euer Reittier ganz sicher daran denken, den Himmel im Auge zu behalten. Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[37009] = { id = 37009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flussbestienausbildung: Zornmotte", description = "Tief in den Wäldern von Nagrand leben ein paar Tiere, die selbst den gefährlichsten Raubtieren entkommen können. Das größte dieser Tiere ist die Zornmotte. Sie ist mit einem übel riechenden Staub bedeckt.\n\nWenn dieser Mottenstaub sogar Wölfe abschrecken kann, wird dies ein guter Test für Eure Flussbestie. Ihr müsst dafür sorgen, dass sie sich nicht davon ablenken lässt, wenn Ihr die Motte zur Strecke bringen wollt.", sourceObjective = "Besiegt die Zornmotte vom Rücken Eurer Ausbildungsflussbestie aus.", completion = "Schön, dass Ihr zurück seid. Es wird eine Weile dauern, diesen Staub wieder loszuwerden.", sourceObjectiveStatus = "unverified-source-field" }
quests[37010] = { id = 37010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flussbestienausbildung: Donnersturm", description = "Die Naturgewalten stellen für einige Tiere oftmals ein Problem dar. Habt Ihr schon mal einen Widder bei Unwetter beobachtet? Sie verstecken sich hinter allem, was größer ist als sie selbst. Vielleicht glauben sie, dass die Welt untergeht. Auf jeden Fall ist es nicht angenehm, wenn man in diesem Moment auf ihrem Rücken sitzt.\n\nIn Nagrand, auf einem windumpeitschten Kliff hoch über der Küste, lebt eine Kreatur, die aus reinem Unwetter besteht. Schwingt Euch auf den Rücken Eurer Flussbestie, um Donnersturm auszuschalten. Dann werden wir ja erleben, ob sich Euer Tier verunsichern lässt.", sourceObjective = "Besiegt Donnersturm vom Rücken Eurer Ausbildungsflussbestie aus.", completion = "Nun, sie ist ein bisschen nass, aber ansonsten ganz vergnügt. Ich werde sie trocknen und dann zu Bett bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37011] = { id = 37011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flussbestienausbildung: Eisenfräser", description = "So, wir haben bisher gegen Feinde in der Luft, an Land und sogar im Unwetter gekämpft. Aber was passiert, wenn sich die Kreaturen unter unseren Füßen befinden? Wir werden es bald herausfinden!\n\nDer Felswurm ist ein gerissener Jäger, der seine Beute aus dem sandigen Untergrund heraus angreift. Viele Tiere Nagrands werden daher durch Erschütterungen der Erde erschreckt. Reitet mit Eurer Flussbestie zu den sandigen Gestaden und versucht, einen der älteren Felswürmer auszuschalten: Eisenfräser.", sourceObjective = "Besiegt Eisenfräser vom Rücken Eurer Ausbildungsflussbestie aus.", completion = "Der Sandwurm ist Geschichte? Gut gemacht. Ich werde das Tier jetzt für Euch schlafen legen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37012] = { id = 37012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flussbestienausbildung: Orcjäger", description = "In den Reihen des Kriegshymnenklans in Nagrand gibt es einige der besten Jäger, die ich leider jemals treffen musste. Wenn es einen ernsthaften Test für Euer zukünftiges Reittier gibt, dann ist es einer ihrer Bestientöter.\n\nDa draußen in Nagrand gibt es einen Orc namens Karak. Sie nennen ihn den \"Großjäger\", denn er hat mehr wilde Bestien erlegt als jeder andere. Schwingt Euch auf Eure Flussbestie und schaltet ihn aus. Im Namen aller armen, geschändeten Kreaturen!", sourceObjective = "Besiegt Karak den Großjäger vom Rücken Eurer Ausbildungsflussbestie aus.", completion = "Der Jäger wurde also zum Gejagten, wie? Euer Tier scheint auch alles unbeschadet überstanden zu haben. Ich werde es abbürsten.", sourceObjectiveStatus = "unverified-source-field" }
quests[37013] = { id = 37013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flussbestienausbildung: Der Garn", description = "Ich habe eine letzte Herausforderung für Euch, Kommandant. Und das wird kein Zuckerschlecken.\n\nMan nennt sie die \"Garn\". Diese nachtschwarzen Wölfe sind doppelt so groß wie normale Wölfe und können einen Mann in Sekundenschnelle in Stücke reißen. Jedes Tier, das noch bei Verstand ist, hat panische Angst vor einem solchen Raubtier.\n\nDa draußen streift ein einsamer Garn umher, der den ganzen Weg von seiner Heimat im Frostfeuergrat bis nach Nagrand gewandert ist. Schwingt Euch auf Eure Flussbestie und schaltet ihn aus. Wenn Ihr beide überlebt, wird Eure Flussbestie für alle zukünftigen Aufgaben wahrhaft bereit sein.", sourceObjective = "Besiegt Malmkiefer vom Rücken Eurer Ausbildungsflussbestie aus.", completion = "Ich muss gestehen, dass ich es zunächst kaum glauben konnte, dass Ihr dieses Viech wirklich ausbilden wollt. Aber jetzt habt Ihr da einen einwandfrei zugerittenen Flussfläzer.\n\nIch bin davon überzeugt, dass Ihr wirklich jedes Tier ausbilden könntet! Gute Arbeit, Kommandant!", sourceObjectiveStatus = "unverified-source-field" }
quests[37014] = { id = 37014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teileauktion", progress = "<Der Machtkristall dieser Einheit wurde entfernt. Wer dafür verantwortlich ist, hat auch die anderen Unterstützungsmodule herausgerissen.\n\nWenn Ihr all diese Gegenstände findet, könnt Ihr sie bestimmt wiederherstellen.>", completion = "Ihr könnt hören, wie sich die Energie in der Einheit aufbaut." }
quests[37015] = { id = 37015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elekkausbildung: Grausame Oger", description = "Dieses Tier ist tief mit seiner Heimat Nagrand verwurzelt. Und ich wette, nach all den Jahren der Domestizierung durch die Draenei wird die Ausbildung ein Kinderspiel.\n\nWir wollen es mal auf ein paar Oger loslassen, die Ihr aus dieser Region kennt. Probiert mal aus, wie es auf den nach Blut und Angst stinkenden gorianischen Tierpeitscher reagiert.", sourceObjective = "Besiegt den gorianischen Tierpeitscher vom Rücken Eures Ausbildungswiesentramplers aus.", completion = "Diese armen Tiere! Ich bin froh, dass Ihr diesen Oger aus dem Verkehr gezogen habt. Kommt morgen wieder, damit wir mit der Ausbildung fortfahren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[37016] = { id = 37016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elekkausbildung: Nachtflügelwindroc", description = "Die Windrocs von Nagrand sind gerissene Jäger, die oftmals im Schwarm auf unaufmerksame Beute niederstoßen. Wenn Euer Tier nicht lernt, auch den Luftraum im Auge zu behalten, wird es schon bald kein Auge mehr haben.\n\nMacht Euch auf nach Nagrand und nehmt es mit dem stärksten Windroc auf, dem Nachtflügelwindroc. Das sollte eine würdige Prüfung für Euch beide sein.", sourceObjective = "Besiegt den Nachtflügelwindroc vom Rücken Eures Ausbildungswiesentramplers aus.", completion = "Von jetzt an wird Euer Reittier ganz sicher daran denken, den Himmel im Auge zu behalten. Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[37017] = { id = 37017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elekkausbildung: Zornmotte", description = "Tief in den Wäldern von Nagrand leben ein paar Tiere, die selbst den gefährlichsten Raubtieren entkommen können. Das größte dieser Tiere ist die Zornmotte. Sie ist mit einem übel riechenden Staub bedeckt.\n\nWenn dieser Mottenstaub sogar Wölfe abschrecken kann, wird dies ein guter Test für Euren Elekk. Ihr müsst dafür sorgen, dass er sich nicht davon ablenken lässt, wenn Ihr die Motte zur Strecke bringen wollt.", sourceObjective = "Besiegt die Zornmotte vom Rücken Eures Ausbildungswiesentramplers aus.", completion = "Schön, dass Ihr zurück seid. Es wird eine Weile dauern, diesen Staub wieder loszuwerden.", sourceObjectiveStatus = "unverified-source-field" }
quests[37018] = { id = 37018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elekkausbildung: Donnersturm", description = "Die Naturgewalten stellen für einige Tiere oftmals ein Problem dar. Habt Ihr schon mal einen Widder bei Unwetter beobachtet? Sie verstecken sich hinter allem, was größer ist als sie selbst. Vielleicht glauben sie, dass die Welt untergeht. Auf jeden Fall ist es nicht angenehm, wenn man in diesem Moment auf ihrem Rücken sitzt.\n\nIn Nagrand, auf einem windumpeitschten Kliff hoch über der Küste, lebt eine Kreatur, die aus reinem Unwetter besteht. Schwingt Euch auf den Rücken Eures Elekks, um Donnersturm auszuschalten. Dann werden wir ja erleben, ob sich Euer Tier verunsichern lässt.", sourceObjective = "Besiegt Donnersturm vom Rücken Eures Ausbildungswiesentramplers aus.", completion = "Nun, er ist ein bisschen nass, aber ansonsten ganz vergnügt. Ich werde ihn trocknen und dann zu Bett bringen.", sourceObjectiveStatus = "unverified-source-field" }
