quests[37020] = { id = 37020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elekkausbildung: Orcjäger", description = "In den Reihen des Kriegshymnenklans in Nagrand gibt es einige der besten Jäger, die ich leider jemals treffen musste. Wenn es einen ernsthaften Test für Euer zukünftiges Reittier gibt, dann ist es einer ihrer Bestientöter.\n\nDa draußen in Nagrand gibt es einen Orc namens Karak. Sie nennen ihn den \"Großjäger\", denn er hat mehr wilde Bestien erlegt als alle anderen seines Klans. Schwingt Euch auf Euren Elekk und schaltet ihn aus. Im Namen aller armen, geschändeten Kreaturen!", sourceObjective = "Besiegt Karak den Großjäger vom Rücken Eures Ausbildungswiesentramplers aus.", completion = "Der Jäger wurde also zum Gejagten, wie? Euer Tier scheint auch alles unbeschadet überstanden zu haben. Ich werde es abbürsten.", sourceObjectiveStatus = "unverified-source-field" }
quests[37021] = { id = 37021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elekkausbildung: Der Garn", description = "Ich habe eine letzte Herausforderung für Euch, Kommandant. Und das wird kein Zuckerschlecken.\n\nMan nennt sie die \"Garn\". Diese nachtschwarzen Wölfe sind doppelt so groß wie normale Wölfe und können einen Mann in Sekundenschnelle in Stücke reißen. Jedes Tier, das noch bei Verstand ist, hat panische Angst vor einem solchen Raubtier.\n\nDa draußen streift ein einsamer Garn umher, der den ganzen Weg von seiner Heimat im Frostfeuergrat bis nach Nagrand gewandert ist. Schwingt Euch auf Euren Elekk und schaltet ihn aus. Wenn Ihr beide überlebt, wird Euer Elekk für alle zukünftigen Aufgaben wahrhaft bereit sein.", sourceObjective = "Besiegt Malmkiefer vom Rücken Eures Ausbildungswiesentramplers aus.", completion = "Da habt Ihr jetzt wirklich ein hervorragendes Reittier, Kommandant. Es wird sich selbst in den härtesten Kämpfen bewähren.\n\nIch muss gestehen, dass ich ein wenig neidisch auf Euch bin! Hier sind die Zügel! Ich werde mich liebevoll um dieses Tier kümmern, wenn Ihr wieder zurück seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[37022] = { id = 37022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolfsausbildung: Grausame Oger", description = "Die Wölfe von Draenor gehören zu den wildesten Bestien überhaupt. Und sie haben sich an den Anblick und Geruch der hiesigen Orcs und Oger gewöhnt. Es sollte also nicht allzu lang dauern, dieses kleine, tödliche Fellknäuel auszubilden.\n\nWir wollen Euren Wolf mal auf ein paar Oger loslassen, die Ihr aus dieser Region kennt. Probiert mal aus, wie er auf den nach Blut und Angst stinkenden gorianischen Tierpeitscher reagiert.", sourceObjective = "Besiegt den gorianischen Tierpeitscher vom Rücken Eures Ausbildungsknurrers aus.", completion = "Diese armen Tiere! Ich bin froh, dass Ihr diesen Oger aus dem Verkehr gezogen habt. Kommt morgen wieder, damit wir mit der Ausbildung fortfahren können.", sourceObjectiveStatus = "unverified-source-field" }
