quests[37025] = { id = 37025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolfsausbildung: Donnersturm", description = "Die Naturgewalten stellen für einige Tiere oftmals ein Problem dar. Habt Ihr schon mal einen Widder bei Unwetter beobachtet? Sie verstecken sich hinter allem, was größer ist als sie selbst. Vielleicht glauben sie, dass die Welt untergeht. Auf jeden Fall ist es nicht angenehm, wenn man in diesem Moment auf ihrem Rücken sitzt.\n\nIn Nagrand, auf einem windumpeitschten Kliff hoch über der Küste, lebt eine Kreatur, die aus reinem Unwetter besteht. Schwingt Euch auf den Rücken Eures Wolfs, um Donnersturm auszuschalten. Dann werden wir ja erleben, ob sich Euer Tier verunsichern lässt.", sourceObjective = "Besiegt Donnersturm vom Rücken Eures Ausbildungsknurrers aus.", completion = "Nun, er ist ein bisschen nass, aber ansonsten ganz vergnügt. Ich werde ihn trocknen und dann zu Bett bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37026] = { id = 37026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolfsausbildung: Eisenfräser", description = "So, wir haben bisher gegen Feinde in der Luft, an Land und sogar im Unwetter gekämpft. Aber was passiert, wenn sich die Kreaturen unter unseren Füßen befinden? Wir werden es bald herausfinden!\n\nDer Felswurm ist ein gerissener Jäger, der seine Beute aus dem sandigen Untergrund heraus angreift. Viele Tiere Nagrands werden daher durch Erschütterungen der Erde erschreckt. Reitet mit Eurem Wolf zu den sandigen Gestaden und versucht, einen der älteren Felswürmer auszuschalten: Eisenfräser.", sourceObjective = "Besiegt Eisenfräser vom Rücken Eures Ausbildungsknurrers aus.", completion = "Der Sandwurm ist Geschichte? Gut gemacht. Ich werde das Tier jetzt für Euch schlafen legen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37027] = { id = 37027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolfsausbildung: Orcjäger", description = "In den Reihen des Kriegshymnenklans in Nagrand gibt es einige der besten Jäger, die ich leider jemals treffen musste. Wenn es einen ernsthaften Test für Euer zukünftiges Reittier gibt, dann ist es einer ihrer Bestientöter.\n\nDa draußen in Nagrand gibt es einen Orc namens Karak. Sie nennen ihn den \"Großjäger\", denn er hat mehr wilde Bestien erlegt als alle anderen seines Klans. Schwingt Euch auf Euren Wolf und schaltet ihn aus. Im Namen aller armen, geschändeten Kreaturen!", sourceObjective = "Besiegt Karak den Großjäger vom Rücken Eures Ausbildungsknurrers aus.", completion = "Der Jäger wurde also zum Gejagten, wie? Euer Tier scheint auch alles unbeschadet überstanden zu haben. Ich werde es abbürsten.", sourceObjectiveStatus = "unverified-source-field" }
quests[37028] = { id = 37028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolfsausbildung: Der Garn", description = "Ich habe eine letzte Herausforderung für Euch, Kommandant. Und das wird kein Zuckerschlecken.\n\nMan nennt sie die \"Garn\". Diese nachtschwarzen Wölfe sind doppelt so groß wie normale Wölfe und können einen Mann in Sekundenschnelle in Stücke reißen. Jedes Tier, das noch bei Verstand ist, hat panische Angst vor einem solchen Raubtier.\n\nDa draußen streift ein einsamer Garn umher, der den ganzen Weg von seiner Heimat im Frostfeuergrat bis nach Nagrand gewandert ist. Schwingt Euch auf Euren Wolf und schaltet ihn aus. Wenn Ihr beide überlebt, wird Euer Wolf für alle zukünftigen Aufgaben wahrhaft bereit sein.", sourceObjective = "Besiegt Malmkiefer vom Rücken Eures Ausbildungsknurrers aus.", completion = "Ich kann kaum glauben, wie schnell es Euch gelungen ist, Euren Wolf auszubilden! Mir scheint, als wäre es erst gestern gewesen, dass ich das kleine, tödliche Fellknäuel unter meine Fittiche genommen habe.\n\nJetzt überlasse ich ihn Euch. Das ist ein schönes, blutrünstiges Reittier, das Ihr da habt. Hier sind die Zügel!", sourceObjectiveStatus = "unverified-source-field" }
quests[37029] = { id = 37029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegel der Schwarzfaust", description = "<Goraluk seufzt... aus Erleichterung? ...oder vielleicht Bedauern?>\n\nEinst wandelte ich als Orc des Schwarzfelsklans voller Stolz hocherhobenen Hauptes durch diese Hallen. Doch das hier ist der falsche Weg. Unsere Hämmer waren dazu bestimmt, Äxte und Schwerter herzustellen... nicht diese Maschinen, die uns ein Fremder eingeflüstert hat.\n\nDer Kriegsherr lässt sich nicht davon abbringen, es sei denn mit Gewalt. Wenn Ihr die Essenzen der mächtigsten Wächter der Gießerei besorgen könnt, kann ich ein Siegel für Euch herstellen, das Euch direkten Zugang zu Schwarzfausts Schmelztiegel verschafft.", sourceObjective = "Sammelt 4 Glut des Berges, 4 steinerne Herzen und 4 Eisensplitter von den Endgegnern jeden Flügels der Schwarzfelsgießerei auf der Schwierigkeitsstufe 'Normal'.", progress = "Ich brauche Essenzen von jedem Wächter der Gießerei, wenn das hier klappen soll.", completion = "Ihr habt es geschafft!\n\n<Goraluk nimmt Euch die Gegenstände aus den Händen und dreht Euch kurz den Rücken zu.>\n\nJetzt werde ich mit diesem Siegel Eure Hand berühren und danach wird sich der Eingang zum Schmelztiegel öffnen, wenn Ihr ihn berührt. Viel Glück.", sourceObjectiveStatus = "unverified-source-field" }
quests[37030] = { id = 37030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegel der Schwarzfaust (Heroisch)", description = "<Goraluk seufzt... aus Erleichterung? ...oder vielleicht Bedauern?>\n\nEinst wandelte ich als Orc des Schwarzfelsklans voller Stolz hocherhobenen Hauptes durch diese Hallen. Doch das hier ist der falsche Weg. Unsere Hämmer waren dazu bestimmt, Äxte und Schwerter herzustellen... nicht diese Maschinen, die uns ein Fremder eingeflüstert hat.\n\nDer Kriegsherr lässt sich nicht davon abbringen, es sei denn mit Gewalt. Wenn Ihr die Essenzen der mächtigsten Wächter der Gießerei besorgen könnt, kann ich ein Siegel für Euch herstellen, das Euch direkten Zugang zu Schwarzfausts Schmelztiegel verschafft.", sourceObjective = "Sammelt 4 Glut des Berges, 4 steinerne Herzen und 4 Eisensplitter von den Endgegnern jeden Flügels der Schwarzfelsgießerei auf der Schwierigkeitsstufe 'Heroisch'.", progress = "Ich brauche Essenzen von jedem Wächter der Gießerei, wenn das hier klappen soll.", completion = "Ihr habt es geschafft!\n\n<Goraluk nimmt Euch die Gegenstände aus den Händen und dreht Euch kurz den Rücken zu.>\n\nJetzt werde ich mit diesem Siegel Eure Hand berühren und danach wird sich der Eingang zum Schmelztiegel öffnen, wenn Ihr ihn berührt. Viel Glück.", sourceObjectiveStatus = "unverified-source-field" }
quests[37031] = { id = 37031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegel der Schwarzfaust (Mythisch)", description = "<Goraluk seufzt... aus Erleichterung? ...oder vielleicht Bedauern?>\n\nEinst wandelte ich als Orc des Schwarzfelsklans voller Stolz hocherhobenen Hauptes durch diese Hallen. Doch das hier ist der falsche Weg. Unsere Hämmer waren dazu bestimmt, Äxte und Schwerter herzustellen... nicht diese Maschinen, die uns ein Fremder eingeflüstert hat.\n\nDer Kriegsherr lässt sich nicht davon abbringen, es sei denn mit Gewalt. Wenn Ihr die Essenzen der mächtigsten Wächter der Gießerei besorgen könnt, kann ich ein Siegel für Euch herstellen, das Euch direkten Zugang zu Schwarzfausts Schmelztiegel verschafft.", sourceObjective = "Sammelt 4 Glut des Berges, 4 steinerne Herzen und 4 Eisensplitter von den Endgegnern jeden Flügels der Schwarzfelsgießerei auf der Schwierigkeitsstufe 'Mythisch'.", progress = "Ich brauche Essenzen von jedem Wächter der Gießerei, wenn das hier klappen soll.", completion = "Ihr habt es geschafft!\n\n<Goraluk nimmt Euch die Gegenstände aus den Händen und dreht Euch kurz den Rücken zu.>\n\nJetzt werde ich mit diesem Siegel Eure Hand berühren und danach wird sich der Eingang zum Schmelztiegel öffnen, wenn Ihr ihn berührt. Viel Glück.", sourceObjectiveStatus = "unverified-source-field" }
quests[37032] = { id = 37032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eberausbildung: Sichelklaue", description = "Der Eber ist auf den felsigen Ebenen von Gorgrond zu Hause. Das sollte es etwas einfacher machen, ihn auszubilden. Wir starten auf bekanntem Territorium... genau wie mit den anderen Tieren.\n\nStellt Euch mit Eurem Tier dem Kampf gegen den riesigen Raptor Sichelklaue, dem schon viele Eber zum Opfer gefallen sind.", sourceObjective = "Besiegt Sichelklaue vom Rücken Eures Ausbildungsebers aus.", completion = "Ein großer Sieg. Aber Euer Tier muss sich nun ausruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37033] = { id = 37033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eberausbildung: Gezz'ran", description = "Viele der Kreaturen Draenors konnten sich in einer höchst feindlichen Umgebung behaupten und entwickeln. Einer der gerissensten Jäger ist der Pirscher.\n\nPirscher können sich ihrer Umgebung anpassen und sich so anschleichen und die Eier ihrer Beute stehlen. Versucht einmal, ob Ihr diesen natürlichen Verteidigungsmechanismus mit Eurem Tier überwinden könnt. In Talador findet Ihr ein solch angemessen gefährliches Raubtier als Gegner.", sourceObjective = "Besiegt Gezz'ran vom Rücken Eures Ausbildungsebers aus.", completion = "Das war eine gefährliche Bestie, die Ihr besiegt habt. Gute Arbeit, ich werde Eurem Reittier etwas Wasser geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[37034] = { id = 37034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eberausbildung: Bulbapore", description = "Weit unten im Süden, bei den Spitzen von Arak, ist das Land von Pilzen überschwemmt worden, die unter Wasser wachsen. In dem Gebiet vermehren sich jetzt überall ungebremst pilzartige Kreaturen.\n\nIndem Ihr den Kampf mit einer solch seltsamen Spezies wie dem Fungusgiganten Bulbapore aufnehmt, könnt Ihr testen, wie Euer Reittier auf ihm unbekannte Raubtiere reagiert.", sourceObjective = "Besiegt Bulbapore vom Rücken Eures Ausbildungsebers aus.", completion = "Ihr habt einen großen Sieg errungen. Ich werde jetzt Euer Reittier für die Nachtruhe bereit machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37035] = { id = 37035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eberausbildung: Grausame Oger", description = "In Nagrand sind die mächtigsten Wildtiere Draenors beheimatet. Und die Oger in dieser Gegend haben gelernt, diese Tiere mithilfe brutaler Techniken zu zähmen.\n\nDabei hat sich ein bestimmter Oger, der gorianische Tierpeitscher, durch besondere Grausamkeit und Blutlust ausgezeichnet. Nehmt es mit ihm auf, um zu sehen, wie Euer Tier auf ihn reagiert.", sourceObjective = "Besiegt den gorianischen Tierpeitscher vom Rücken Eures Ausbildungsebers aus.", completion = "Diese Tiere erholen sich sehr schnell. Wir wollen uns jetzt auch zur Nachtruhe begeben. Ihr habt Euch tapfer geschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37036] = { id = 37036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eberausbildung: Nachtflügelwindroc", description = "Die Windrocs von Nagrand sind gerissene Jäger, die oftmals im Schwarm auf unaufmerksame Beute niederstoßen. Wenn Euer Tier nicht lernt, auch den Luftraum im Auge zu behalten, wird es schon bald keines mehr haben.\n\nBegebt Euch nach Nagrand und nehmt es mit dem stärksten Windroc auf, dem Nachtflügelwindroc. Das sollte eine würdige Prüfung für Euer Reittier sein.", sourceObjective = "Besiegt den Nachtflügelwindroc vom Rücken Eures Ausbildungsebers aus.", completion = "Von jetzt an wird Euer Reittier ganz sicher daran denken, den Himmel im Auge zu behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[37037] = { id = 37037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eberausbildung: Zornmotte", description = "Tief in den Wäldern von Nagrand leben ein paar Tiere, die selbst den gefährlichsten Raubtieren entkommen können. Das größte dieser Tiere ist die Zornmotte. Sie ist mit einem übel riechenden Staub bedeckt.\n\nWenn dieser Mottenstaub sogar die Wölfe abschrecken kann, wird dies ein guter Test für Euren Eber. Sorgt dafür, dass er sich nicht davon ablenken lässt, und schaltet diese Motte aus.", sourceObjective = "Besiegt die Zornmotte vom Rücken Eures Ausbildungsebers aus.", completion = "Schön, dass Ihr zurück seid. Es wird eine Weile dauern, diesen Staub wieder loszuwerden.", sourceObjectiveStatus = "unverified-source-field" }
quests[37038] = { id = 37038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eberausbildung: Donnersturm", description = "Die Naturgewalten stellen für einige Tiere oftmals ein Problem dar. Selbst der mächtigste Wolf versteckt sich manchmal, wenn er das Donnern in der Ferne hört.\n\nIn Nagrand, auf einem windumpeitschten Kliff hoch über der Küste, lebt eine Kreatur, die aus reinem Unwetter besteht. Schwingt Euch auf den Rücken Eures Tieres, um gegen Donnersturm anzutreten. Dann werden wir ja erleben, wie sich Euer Tier verhält.", sourceObjective = "Besiegt Donnersturm vom Rücken Eures Ausbildungsebers aus.", completion = "Euer Reittier ist ein bisschen nass, aber ansonsten ganz vergnügt. Ich werde es trocknen und dann dafür sorgen, dass es ruht.", sourceObjectiveStatus = "unverified-source-field" }
quests[37039] = { id = 37039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eberausbildung: Eisenfräser", description = "So, Ihr habt bis jetzt Feinde in der Luft, an Land und sogar im Unwetter besiegt. Aber jetzt geht es gegen Kreaturen, die sich unter Euren Füßen befinden.\n\nDer Felswurm ist ein gerissener Jäger, der seine Beute aus dem sandigen Untergrund heraus angreift. Viele Tiere Nagrands werden daher durch Erschütterungen der Erde erschreckt. Begebt Euch mit Eurem Reittier zu den sandigen Gestaden und versucht, einen der älteren Felswürmer auszuschalten: Eisenfräser.", sourceObjective = "Besiegt Eisenfräser vom Rücken Eures Ausbildungsebers aus.", completion = "Ihr steht auf sicheren Beinen, auch wenn die Erde bebt. Bewundernswert.\n\nGönnt jetzt Eurem Reittier die verdiente Nachtruhe.", sourceObjectiveStatus = "unverified-source-field" }
quests[37040] = { id = 37040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eberausbildung: Orcjäger", description = "In den Reihen des Kriegshymnenklans in Nagrand gibt es einige der besten Jäger von ganz Draenor. Ihre Hauptjäger stellen eine anspruchsvolle Prüfung für Euer Reittier dar.\n\nDa draußen in Nagrand gibt es einen Orc. Er nennt sich Karak der Große Jäger. Er hat mehr wilde Bestien erlegt als alle anderen seines Klans. Reitet ihm auf Eurem Reittier entgegen und schaltet ihn aus, um all seine Opfer zu rächen.", sourceObjective = "Besiegt Karak den Großjäger vom Rücken Eures Ausbildungsebers aus.", completion = "Ah, Ihr habt den Jäger gejagt. Damit habt Ihr vielen Kreaturen einen guten Dienst erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37041] = { id = 37041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eberausbildung: Der Garn", description = "In der letzten Prüfung für Euer Reittier geht es gegen eine der schrecklichsten Kreaturen dieses Landes.\n\nMan nennt sie die \"Garn\". Diese nachtschwarzen Wölfe sind doppelt so groß wie normale Wölfe und können einen Orc in Sekundenschnelle in Stücke reißen. Die Tiere dieser Gegend haben vollkommen zu Recht Angst vor ihnen.\n\nDa draußen streift ein einsamer Garn umher, der Nagrand zu seiner Heimat gemacht hat. Schwingt Euch auf Euren Eber und schaltet ihn aus. Wenn Ihr beide überlebt, wird Euer Eber für alle zukünftigen Aufgaben wahrhaft bereit sein.", sourceObjective = "Besiegt Malmkiefer vom Rücken Eures Ausbildungsebers aus.", completion = "Nach diesem Sieg über den Garn ist Euer Eber jetzt für den echten Kampf bereit. Hier sind die Zügel. Möget Ihr immer Gefährten bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[37043] = { id = 37043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alteisen", description = "Wir können im Arsenal aus alten Rüstungsteilen der Eisernen Horde, die Ihr einsammelt, neue Ausrüstung machen. Sie wird nicht die stärkste der Welt sein, sieht aber gut aus.\n\nBesorgt ein paar alte Rüstungsteile der Eisernen Horde und kommt wieder zu mir. Ich werde Euch einen schönen Wappenrock für Eure Bemühungen machen.", sourceObjective = "Sammelt 5 Rüstungsteile der Eisernen Horde von der Eisernen Horde in Draenor.", progress = "Habt Ihr die Rüstungsteile?", completion = "Diese Rüstungsteile werden genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37044] = { id = 37044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Außergewöhnliche Erfindungen", description = "Hier in der Werkstatt ist 'ne Menge los. Wir machen ständig neue Erfindungen. Ihr findet sie hinter mir auf der Werkbank.\n\nGeht und holt Euch die sensationelle Erfindung von heute. Verwendung auf eigene Gefahr.", sourceObjective = "Holt eine Erfindung von der Werkbank in der Goblinwerkstatt.", completion = "Ziemliche tolle Erfindung habt Ihr da.", sourceObjectiveStatus = "unverified-source-field" }
quests[37045] = { id = 37045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wert im Verborgenen", description = "Hier in der Wiederverwertung sichten wir alle zusätzlichen Materialien, die Eure Anhänger von draußen mitbringen, um alles zu erhalten, was nützlich ist.\n\nIch habe von unseren Leuten eine Ladung Material bekommen, die ich noch nicht durchforsten konnte. Vielleicht könnt Ihr sie rüber zum Verbrenner bringen und nachschauen, ob etwas Verwertbares dabei ist?", sourceObjective = "Verwendet die kleine Tasche mit geborgenen Teilen in der Nähe des Verbrenners in Eurer Wiederverwertung.", progress = "Habt Ihr schon die Tasche mit den Teilen durchstöbern können?", completion = "Mehr war nicht drin? Aber das macht nichts. Manchmal gehen wir leer aus und manchmal ziehen wir das große Los.\n\nHier habe ich noch ein paar neue Sachen von unserem letzten Ausflug. Seht sie Euch an.\n\nViel Glück damit!", sourceObjectiveStatus = "unverified-source-field" }
quests[37046] = { id = 37046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anhänger anwerben", description = "Hey, Boss. Ich bin Euer neuer Talentsucher. \n\nDie Schenke ist ein perfekter Ort für Abenteurer, um sich nach langer Reise auszuruh'n. Außerdem ist sie ein toller Ort, um sie zum Beitritt zu unserer Sache zu überred'n.\n\nIch hab da 'n paar Rekruten, die Ihr Euch anschau'n könnt. Wenn Ihr einen auswählt, bekommt Ihr auch 'ne Belohnung für Eure Mühen.", sourceObjective = "Rekrutiert einen Anhänger von Akanja in der Frostwallschenke.", progress = "Schon 'nen passenden Rekruten gefund'n?", completion = "Schön, dass Euch einer gefall'n hat!\n\nSchaut jede Woche vorbei, um nach neuen Rekruten zu frag'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[37047] = { id = 37047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geschenk des Lichts", sourceObjective = "Das Licht hat mich mit neugefundener Kraft gesegnet, Kommandant.\n\nNiemand wird unserer Überzeugung im Weg stehen!Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
quests[37048] = { id = 37048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grollhufausbildung: Riesenhauer", description = "Der nächste Schritt bei der Ausbildung Eures Reittieres für den Krieg ist es, das Tier an den Anblick und die Geräusche des Gefechtes zu gewöhnen. Wenn es keine vernünftige Ausbildung genossen hat, könnte es sich sonst zum denkbar ungünstigsten Zeitpunkt erschrecken.\n\nReitet mit diesem kleinen, aber einsatzbereiten Grollhuf zu den Ebenen des Schattenmondtales und sucht dort nach dem größten Wildtier, das Ihr finden könnt. An einem solchen Gegner kann der kleine Grollhuf wachsen.", sourceObjective = "Besiegt Riesenhauer vom Rücken Eures Ausbildungsgrollhufs aus.", completion = "Euer Grollhuf scheint müde, aber glücklich zu sein. Ihr habt Euch tapfer geschlagen. Gönnen wir dem Tier jetzt etwas Ruhe.", sourceObjectiveStatus = "unverified-source-field" }
quests[37049] = { id = 37049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grollhufausbildung: Rakkiri", description = "Euer Grollhuf fühlt sich in seiner Heimat, dem Frostfeuergrat, am wohlsten. Aus diesem Grund werden wir dort auch mit der Ausbildung beginnen.\n\nDie eisigen Ebenen da draußen sind das Zuhause eines nach Blut und Tod dürstenden Wildtieres. Der geflügelte Schrecken Rakkiri ist in der ganzen Gegend gefürchtet. Der Kampf gegen ihn wird ein guter Test für Euer zukünftiges Reittier sein.", sourceObjective = "Besiegt Rakkiri vom Rücken Eures Ausbildungsgrollhufs aus.", completion = "Der Grollhuf ist in guter Verfassung. Eure Ausbildung scheint dem Tier gut zu tun. Aber jetzt braucht es etwas Ruhe.", sourceObjectiveStatus = "unverified-source-field" }
quests[37050] = { id = 37050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grollhufausbildung: Sichelklaue", description = "Viele Tiere verstecken sich beim Anblick eines gefährlichen Raubtieres. Und im Gebiet der abgeschiedenen Klippen von Gorgrond lebt eines der gefährlichsten von ihnen. Das wird Eure nächste Herausforderung.\n\nReitet mit Eurem Tier zum Nest des mächtigen Sichelklaue und versucht, diesen gefährlichen Gegner zu erlegen.", sourceObjective = "Besiegt Sichelklaue vom Rücken Eures Ausbildungsgrollhufs aus.", completion = "Ein großer Sieg. Aber Euer Tier muss sich nun ausruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37051] = { id = 37051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grollhufausbildung: Gezz'ran", description = "Viele der Kreaturen Draenors konnten sich in einer höchst feindlichen Umgebung behaupten und entwickeln. Einer der gerissensten Jäger ist der Pirscher.\n\nPirscher können sich ihrer Umgebung anpassen und sich so anschleichen und die Eier ihrer Beute stehlen. Versucht einmal, ob Ihr diesen natürlichen Verteidigungsmechanismus mit Eurem Tier überwinden könnt. In Talador findet Ihr ein solch angemessen gefährliches Raubtier als Gegner.", sourceObjective = "Besiegt Gezz'ran vom Rücken Eures Ausbildungsgrollhufs aus.", completion = "Das war eine gefährliche Bestie, die Ihr besiegt habt. Gute Arbeit, ich werde Eurem Reittier etwas Wasser geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[37052] = { id = 37052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grollhufausbildung: Bulbapore", description = "Weit unten im Süden, bei den Spitzen von Arak, ist das Land von Pilzen überschwemmt worden, die unter Wasser wachsen. In dem Gebiet vermehren sich jetzt überall ungebremst pilzartige Kreaturen.\n\nIndem Ihr den Kampf mit einer solch seltsamen Spezies wie dem Fungusgiganten Bulbapore aufnehmt, könnt Ihr testen, wie Euer Reittier auf ihm unbekannte Raubtiere reagiert.", sourceObjective = "Besiegt Bulbapore vom Rücken Eures Ausbildungsgrollhufs aus.", completion = "Ihr habt einen großen Sieg errungen. Ich werde jetzt Euer Reittier für die Nachtruhe bereit machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37053] = { id = 37053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grollhufausbildung: Grausame Oger", description = "In Nagrand sind die mächtigsten Wildtiere Draenors beheimatet. Und die Oger in dieser Gegend haben gelernt, diese Tiere mithilfe brutaler Techniken zu zähmen.\n\nDabei hat sich ein bestimmter Oger, der gorianische Tierpeitscher, durch besondere Grausamkeit und Blutlust ausgezeichnet. Nehmt es mit ihm auf, um zu sehen, wie Euer Tier auf ihn reagiert.", sourceObjective = "Besiegt den gorianischen Tierpeitscher vom Rücken Eures Ausbildungsgrollhufs aus.", completion = "Diese Tiere erholen sich sehr schnell. Wir wollen uns jetzt auch zur Nachtruhe begeben. Ihr habt Euch tapfer geschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37054] = { id = 37054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grollhufausbildung: Nachtflügelwindroc", description = "Die Windrocs von Nagrand sind gerissene Jäger, die oftmals im Schwarm auf die unaufmerksame Beute niederstoßen. Wenn Euer Tier nicht lernt, auch den Luftraum im Auge zu behalten, wird es schon bald keines mehr haben.\n\nBegebt Euch nach Nagrand und nehmt es mit dem stärksten Windroc auf, dem Nachtflügelwindroc. Das sollte eine würdige Prüfung für Euch beide sein.", sourceObjective = "Besiegt den Nachtflügelwindroc vom Rücken Eures Ausbildungsgrollhufs aus.", completion = "Von jetzt an wird Euer Reittier ganz sicher daran denken, den Himmel im Auge zu behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[37055] = { id = 37055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grollhufausbildung: Zornmotte", description = "Tief in den Wäldern von Nagrand leben ein paar Tiere, die selbst den gefährlichsten Raubtieren entkommen können. Das größte dieser Tiere ist die Zornmotte. Sie ist mit einem übel riechenden Staub bedeckt.\n\nWenn dieser Mottenstaub sogar die Wölfe abschrecken kann, wird dies ein guter Test für Euren Grollhuf. Sorgt dafür, dass er sich nicht davon ablenken lässt, und schaltet diese Motte aus.", sourceObjective = "Besiegt die Zornmotte vom Rücken Eures Ausbildungsgrollhufs aus.", completion = "Schön, dass Ihr zurück seid. Es wird eine Weile dauern, diesen Staub wieder loszuwerden.", sourceObjectiveStatus = "unverified-source-field" }
quests[37056] = { id = 37056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grollhufausbildung: Donnersturm", description = "Die Naturgewalten stellen für einige Tiere oftmals ein Problem dar. Selbst der mächtigste Wolf versteckt sich manchmal, wenn er das Donnern in der Ferne hört.\n\nIn Nagrand, auf einem windumpeitschten Kliff hoch über der Küste, lebt eine Kreatur, die aus reinem Unwetter besteht. Schwingt Euch auf den Rücken Eures Tieres, um gegen Donnersturm anzutreten. Dann werden wir ja erleben, wie sich Euer Tier verhält.", sourceObjective = "Besiegt Donnersturm vom Rücken Eures Ausbildungsgrollhufs aus.", completion = "Euer Reittier ist ein bisschen durchnässt, aber ansonsten ganz vergnügt. Ich reibe es trocken und sorge dafür, dass es ruht.", sourceObjectiveStatus = "unverified-source-field" }
quests[37057] = { id = 37057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grollhufausbildung: Eisenfräser", description = "So, Ihr habt bis jetzt Feinde in der Luft, an Land und sogar im Unwetter besiegt. Aber jetzt geht es gegen Kreaturen, die sich unter Euren Füßen befinden.\n\nDer Felswurm ist ein gerissener Jäger, der seine Beute aus dem sandigen Untergrund heraus angreift. Viele Tiere Nagrands werden daher durch Erschütterungen der Erde erschreckt. Begebt Euch mit Eurem Reittier zu den sandigen Gestaden und versucht, einen der älteren Felswürmer auszuschalten: Eisenfräser.", sourceObjective = "Besiegt Eisenfräser vom Rücken Eures Ausbildungsgrollhufs aus.", completion = "Ihr steht auf sicheren Beinen, auch wenn die Erde bebt. Bewundernswert.\n\nGönnt jetzt Eurem Reittier die verdiente Nachtruhe.", sourceObjectiveStatus = "unverified-source-field" }
quests[37058] = { id = 37058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grollhufausbildung: Orcjäger", description = "In den Reihen des Kriegshymnenklans in Nagrand gibt es einige der besten Jäger von ganz Draenor. Ihre Hauptjäger stellen eine anspruchsvolle Prüfung für Euer Reittier dar.\n\nDa draußen in Nagrand gibt es einen Orc. Er nennt sich Karak der Große Jäger. Er hat mehr wilde Bestien erlegt als alle anderen seines Klans. Reitet ihm auf Eurem Reittier entgegen und schaltet ihn aus, um all seine Opfer zu rächen.", sourceObjective = "Besiegt Karak den Großjäger vom Rücken Eures Ausbildungsgrollhufs aus.", completion = "Ah, Ihr habt den Jäger gejagt. Damit habt Ihr vielen Kreaturen einen guten Dienst erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37059] = { id = 37059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grollhufausbildung: Der Garn", description = "In der letzten Prüfung für Euer Reittier geht es gegen eine der schrecklichsten Kreaturen dieses Landes.\n\nMan nennt sie die \"Garn\". Diese nachtschwarzen Wölfe sind doppelt so groß wie normale Wölfe und können einen Orc in Sekundenschnelle in Stücke reißen. Die Tiere dieser Gegend haben vollkommen zu Recht Angst vor ihnen.\n\nDa draußen streift ein einsamer Garn umher, der Nagrand zu seiner Heimat gemacht hat. Schwingt Euch auf Euren Grollhuf und schaltet ihn aus. Wenn Ihr beide überlebt, wird Euer Grollhuf für alle zukünftigen Aufgaben wahrhaft bereit sein.", sourceObjective = "Besiegt Malmkiefer vom Rücken Eures Ausbildungsgrollhufs aus.", completion = "Dieser Grollhuf ist jetzt vollständig ausgebildet und bereit, Euch als Reittier zu dienen. Kümmert Euch gut um das Tier. Ich hoffe, Euch beide bald wieder unversehrt zurück zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37060] = { id = 37060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschollen im Übergang", description = "<Mein Herr/Meine Dame>, das Lagerhaus ist komplett funktionsfähig. Ich habe mich darum gekümmert, dass Eure Vorräte sicher eingelagert und ausgewiesen sind.\n\nDummerweise musste ich im Zuge der weiteren Betriebsprüfung feststellen, dass uns ein paar Kisten mit überschüssigem Material abhandengekommen sind. Vermutlich hat einer von den Trägern sie verlegt.\n\nFalls Ihr bei Euren Runden auf überschüssige Kisten stoßt, bringt sie bitte zu mir, damit ich sie in unser Geschäftsbuch eintragen kann.", sourceObjective = "Sammelt 5 Kisten überschüssigen Materials.", progress = "Hallo Kommandant, was kann ich für Euch tun?", completion = "Vielen Dank. Laut Geschäftsbuch waren das alle, die uns gefehlt haben.\nDafür werden die Peons heute Abend die Latrinen sauber machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[37062] = { id = 37062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das A und O des Handelns", description = "Um sich die Zeit zu vertreiben, nehmen Händler gerne ab und zu Getränke inspirierender Natur zu sich, wenn Ihr wisst, was ich meine.\n\nManchmal trinken sie ein wenig zu viel. Euer Händler könnte aus dem Tor gestolpert und irgendwo unter einem Baum umgekippt sein. Das kommt schon mal vor.\n\nZum Glück habe ich ein Getränk, um angeschlagene Händler wieder munter zu machen. Ein Tropfen und sie sind wieder äußerst arbeitswillig.", sourceObjective = "Findet den vermissten Händler und macht ihn wieder munter.", progress = "Handeln ist nicht immer das Aufregendste, was man machen kann, aber ich habe wirklich Spaß daran.", completion = "Jetzt habt Ihr eins meiner Berufsgeheimnisse erfahren, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[37063] = { id = 37063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elekkausbildung: Grausame Oger", description = "Dieses Tier ist tief mit seiner Heimat Nagrand verwurzelt. Nach all den Jahren der Domestizierung durch die Draenei sollte die Ausbildung kein Problem sein.\n\nWir wollen es mal auf ein paar Oger loslassen, die Ihr aus dieser Region kennt. Probiert mal aus, wie es auf den nach Blut und Angst stinkenden gorianischen Tierpeitscher reagiert.", sourceObjective = "Besiegt den gorianischen Tierpeitscher vom Rücken Eures Ausbildungswiesentramplers aus.", completion = "Diese Tiere erholen sich sehr schnell. Wir wollen uns jetzt auch zur Nachtruhe begeben. Ihr habt Euch tapfer geschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37064] = { id = 37064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elekkausbildung: Nachtflügelwindroc", description = "Die Windrocs von Nagrand sind gerissene Jäger, die oftmals im Schwarm auf unaufmerksame Beute niederstoßen. Wenn Euer Tier nicht lernt, auch den Luftraum im Auge zu behalten, wird es schon bald keines mehr haben.\n\nBegebt Euch nach Nagrand und nehmt es mit dem stärksten Windroc auf, dem Nachtflügelwindroc. Das sollte eine würdige Prüfung für Euer Reittier sein.", sourceObjective = "Besiegt den Nachtflügelwindroc vom Rücken Eures Ausbildungswiesentramplers aus.", completion = "Von jetzt an wird Euer Reittier ganz sicher daran denken, den Himmel im Auge zu behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[37065] = { id = 37065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elekkausbildung: Zornmotte", description = "Tief in den Wäldern von Nagrand leben ein paar Tiere, die selbst den gefährlichsten Raubtieren entkommen können. Das größte dieser Tiere ist die Zornmotte. Sie ist mit einem übel riechenden Staub bedeckt.\n\nWenn dieser Mottenstaub sogar die Wölfe abschrecken kann, wird dies ein guter Test für Euren Elekk. Sorgt dafür, dass er sich nicht davon ablenken lässt, und schaltet diese Motte aus.", sourceObjective = "Besiegt die Zornmotte vom Rücken Eures Ausbildungswiesentramplers aus.", completion = "Schön, dass Ihr zurück seid. Es wird eine Weile dauern, diesen Staub wieder loszuwerden.", sourceObjectiveStatus = "unverified-source-field" }
quests[37066] = { id = 37066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elekkausbildung: Donnersturm", description = "Die Naturgewalten stellen für einige Tiere oftmals ein Problem dar. Selbst der mächtigste Wolf versteckt sich manchmal, wenn er das Donnern in der Ferne hört.\n\nIn Nagrand, auf einem windumpeitschten Kliff hoch über der Küste, lebt eine Kreatur, die aus reinem Unwetter besteht. Schwingt Euch auf den Rücken Eures Tieres, um gegen Donnersturm anzutreten. Dann werden wir ja erleben, wie sich Euer Tier verhält.", sourceObjective = "Besiegt Donnersturm vom Rücken Eures Ausbildungswiesentramplers aus.", completion = "Euer Reittier ist ein bisschen nass, aber ansonsten ganz vergnügt. Ich werde es trocknen und dann dafür sorgen, dass es ruht.", sourceObjectiveStatus = "unverified-source-field" }
quests[37067] = { id = 37067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elekkausbildung: Eisenfräser", description = "So, Ihr habt bis jetzt Feinde in der Luft, an Land und sogar im Unwetter besiegt. Aber jetzt geht es gegen Kreaturen, die sich unter Euren Füßen befinden.\n\nDer Felswurm ist ein gerissener Jäger, der seine Beute aus dem sandigen Untergrund heraus angreift. Viele Tiere Nagrands werden daher durch Erschütterungen der Erde erschreckt. Begebt Euch mit Eurem Reittier zu den sandigen Gestaden und versucht, einen der älteren Felswürmer auszuschalten: Eisenfräser.", sourceObjective = "Besiegt Eisenfräser vom Rücken Eures Ausbildungswiesentramplers aus.", completion = "Ihr steht auf sicheren Beinen, auch wenn die Erde bebt. Bewundernswert.\n\nGönnt jetzt Eurem Reittier die verdiente Nachtruhe.", sourceObjectiveStatus = "unverified-source-field" }
quests[37068] = { id = 37068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elekkausbildung: Orcjäger", description = "In den Reihen des Kriegshymnenklans in Nagrand gibt es einige der besten Jäger von ganz Draenor. Ihre Bestientöter stellen eine anspruchsvolle Prüfung für Euer Reittier dar.\n\nDa draußen in Nagrand gibt es einen Orc. Er nennt sich Karak der Großjäger. Er hat mehr wilde Bestien erlegt als alle anderen seines Klans. Reitet ihm auf Eurem Reittier entgegen und schaltet ihn aus, um all seine Opfer zu rächen.", sourceObjective = "Besiegt Karak den Großjäger vom Rücken Eures Ausbildungswiesentramplers aus.", completion = "Ah, Ihr habt den Jäger gejagt. Damit habt Ihr vielen Kreaturen einen guten Dienst erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37069] = { id = 37069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elekkausbildung: Der Garn", description = "In der letzten Prüfung für Euer Reittier geht es gegen eine der schrecklichsten Kreaturen dieses Landes.\n\nMan nennt sie die \"Garn\". Diese nachtschwarzen Wölfe sind doppelt so groß wie normale Wölfe und können einen Orc in Sekundenschnelle in Stücke reißen. Die Tiere dieser Gegend haben vollkommen zu Recht Angst vor ihnen.\n\nDa draußen streift ein einsamer Garn umher, der Nagrand zu seiner Heimat gemacht hat. Schwingt Euch auf Euren Elekk und schaltet ihn aus. Wenn Ihr beide überlebt, wird Euer Elekk für alle zukünftigen Aufgaben wahrhaft bereit sein.", sourceObjective = "Besiegt Malmkiefer vom Rücken Eures Ausbildungswiesentramplers aus.", completion = "Dieses schöne Tier wird Euch ein guter Gefährte in zukünftigen Kämpfen sein. Hier sind die Zügel. Seid hart, aber gerecht bei der Behandlung dieser edlen Kreatur.", sourceObjectiveStatus = "unverified-source-field" }
quests[37070] = { id = 37070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht des Nethers", sourceObjective = "An Eurer Seite zu kämpfen, hat meine Verbindung zum Nether so sehr gestärkt wie noch nie zuvor, Kommandant.\n\nIch werde meine neue Macht nutzen, um den Tod auf Eure Feinde niederregnen zu lassen. Sie werden lernen, Euch zu fürchten.Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
quests[37071] = { id = 37071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flussbestienausbildung: Gezz'ran", description = "Dieses mächtige Tier hat schon einige Jahre in der Wildnis von Talador verbracht. Wir werden auch dort mit der Ausbildung beginnen. Es ist bereits einigermaßen zahm, also wird die Ausbildung wohl nicht so lange wie bei den anderen dauern.\n\nIhr wisst ja, dass Pirscher sich ihrer Umgebung anpassen und sich so anschleichen und die Eier ihrer Beute stehlen können. Versucht einmal, ob Ihr diesen natürlichen Verteidigungsmechanismus mit Eurer Flussbestie überwinden könnt.", sourceObjective = "Besiegt Gezz'ran vom Rücken Eurer Ausbildungsflussbestie aus.", completion = "Das war eine gefährliche Bestie, die Ihr besiegt habt. Gute Arbeit, ich werde Eurem Reittier etwas Wasser geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[37072] = { id = 37072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flussbestienausbildung: Bulbapore", description = "Weit unten im Süden, bei den Spitzen von Arak, ist das Land von Pilzen überschwemmt worden, die unter Wasser wachsen. In dem Gebiet vermehren sich jetzt überall ungebremst pilzartige Kreaturen.\n\nIndem Ihr den Kampf mit einer solch seltsamen Spezies wie dem Fungusgiganten Bulbapore aufnehmt, könnt Ihr testen, wie Euer Reittier auf ihm unbekannte Gegner reagiert.", sourceObjective = "Besiegt Bulbapore vom Rücken Eurer Ausbildungsflussbestie aus.", completion = "Ihr habt einen großen Sieg errungen. Ich werde jetzt Euer Reittier für die Nachtruhe bereit machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37073] = { id = 37073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flussbestienausbildung: Grausame Oger", description = "In Nagrand sind die wildesten Bestien Draenors beheimatet. Und die Oger in dieser Gegend haben gelernt, diese Tiere mithilfe brutaler Techniken zu zähmen.\n\nDabei hat sich ein bestimmter Oger, der gorianische Tierpeitscher, durch besondere Grausamkeit und Blutlust ausgezeichnet. Nehmt es mit ihm auf, um zu sehen, wie Euer Tier auf ihn reagiert.", sourceObjective = "Besiegt den gorianischen Tierpeitscher vom Rücken Eurer Ausbildungsflussbestie aus.", completion = "Diese Tiere erholen sich sehr schnell. Wir wollen uns jetzt auch zur Nachtruhe begeben. Ihr habt Euch tapfer geschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37074] = { id = 37074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flussbestienausbildung: Nachtflügelwindroc", description = "Die Windrocs von Nagrand sind gerissene Jäger, die oftmals im Schwarm auf unaufmerksame Beute niederstoßen. Wenn Euer Tier nicht lernt, auch den Luftraum im Auge zu behalten, wird es schon bald keines mehr haben.\n\nBegebt Euch nach Nagrand und nehmt es mit dem stärksten Windroc auf, dem Nachtflügelwindroc. Das sollte eine würdige Prüfung für Euer Reittier sein.", sourceObjective = "Besiegt den Nachtflügelwindroc vom Rücken Eurer Ausbildungsflussbestie aus.", completion = "Von jetzt an wird Euer Reittier ganz sicher daran denken, den Himmel im Auge zu behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[37075] = { id = 37075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flussbestienausbildung: Zornmotte", description = "Tief in den Wäldern von Nagrand leben ein paar Tiere, die selbst den gefährlichsten Raubtieren entkommen können. Das größte dieser Tiere ist die Zornmotte. Sie ist mit einem übel riechenden Staub bedeckt.\n\nWenn dieser Mottenstaub sogar die Wölfe abschrecken kann, wird dies ein guter Test für Eure Flussbestie. Sorgt dafür, dass sie sich nicht davon ablenken lässt, und schaltet diese Motte aus.", sourceObjective = "Besiegt die Zornmotte vom Rücken Eurer Ausbildungsflussbestie aus.", completion = "Schön, dass Ihr zurück seid. Es wird eine Weile dauern, diesen Staub wieder loszuwerden.", sourceObjectiveStatus = "unverified-source-field" }
quests[37076] = { id = 37076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flussbestienausbildung: Donnersturm", description = "Die Naturgewalten stellen für einige Tiere oftmals ein Problem dar. Selbst der mächtigste Wolf versteckt sich manchmal, wenn er das Donnern in der Ferne hört.\n\nIn Nagrand, auf einem windumpeitschten Kliff hoch über der Küste, lebt eine Kreatur, die aus reinem Unwetter besteht. Schwingt Euch auf den Rücken Eures Tieres, um gegen Donnersturm anzutreten. Dann werden wir ja erleben, wie sich Euer Tier verhält.", sourceObjective = "Besiegt Donnersturm vom Rücken Eurer Ausbildungsflussbestie aus.", completion = "Euer Reittier ist ein bisschen nass, aber ansonsten ganz vergnügt. Ich werde es trocknen und dann dafür sorgen, dass es ruht.", sourceObjectiveStatus = "unverified-source-field" }
quests[37077] = { id = 37077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flussbestienausbildung: Eisenfräser", description = "So, Ihr habt bis jetzt Feinde in der Luft, an Land und sogar im Unwetter besiegt. Aber jetzt geht es gegen Kreaturen, die sich unter Euren Füßen befinden.\n\nDer Felswurm ist ein gerissener Jäger, der seine Beute aus dem sandigen Untergrund heraus angreift. Viele Tiere Nagrands werden daher durch Erschütterungen der Erde erschreckt. Begebt Euch mit Eurem Reittier zu den sandigen Gestaden und versucht, einen der älteren Felswürmer auszuschalten: Eisenfräser.", sourceObjective = "Besiegt Eisenfräser vom Rücken Eurer Ausbildungsflussbestie aus.", completion = "Ihr steht auf sicheren Beinen, auch wenn die Erde bebt. Bewundernswert.\n\nGönnt jetzt Eurem Reittier die verdiente Nachtruhe.", sourceObjectiveStatus = "unverified-source-field" }
quests[37078] = { id = 37078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flussbestienausbildung: Orcjäger", description = "In den Reihen des Kriegshymnenklans in Nagrand gibt es einige der besten Jäger von ganz Draenor. Ihre Bestientöter stellen eine anspruchsvolle Prüfung für Euer Reittier dar.\n\nDa draußen in Nagrand gibt es einen Orc. Er nennt sich Karak der Großjäger. Er hat mehr wilde Bestien erlegt als alle anderen seines Klans. Reitet ihm auf Eurem Reittier entgegen und schaltet ihn aus, um all seine Opfer zu rächen.", sourceObjective = "Besiegt Karak den Großjäger vom Rücken Eurer Ausbildungsflussbestie aus.", completion = "Ah, Ihr habt den Jäger gejagt. Damit habt Ihr vielen Kreaturen einen guten Dienst erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37079] = { id = 37079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flussbestienausbildung: Der Garn", description = "In der letzten Prüfung für Euer Reittier geht es gegen eine der schrecklichsten Kreaturen dieses Landes.\n\nMan nennt sie die \"Garn\". Diese nachtschwarzen Wölfe sind doppelt so groß wie normale Wölfe und können einen Orc in Sekundenschnelle in Stücke reißen. Die Tiere dieser Gegend haben vollkommen zu Recht Angst vor ihnen.\n\nDa draußen streift ein einsamer Garn umher, der Nagrand zu seiner Heimat gemacht hat. Schwingt Euch auf Eure Flussbestie und schaltet ihn aus. Wenn Ihr beide überlebt, wird Eure Flussbestie für alle zukünftigen Aufgaben wahrhaft bereit sein.", sourceObjective = "Besiegt Malmkiefer vom Rücken Eurer Ausbildungsflussbestie aus.", completion = "Bevor ich hier hergekommen war hatte ich noch nie ein derartiges Tier gesehen. Aber Ihr habt es ausgebildet. Das war wahrlich keine leichte Aufgabe. Nehmt diese Zügel, Ihr habt sie Euch verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[37080] = { id = 37080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großartiges Gemetzel", sourceObjective = "Das Blut unsrer gefall'nen Feinde hat meinen Durst noch nicht gelöscht, Kommandant.\n\nIch hab' 'nen Trick auf Lager, der das ändern könnte.Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
quests[37081] = { id = 37081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennender Zorn", sourceObjective = "Wir haben unseren Feinden gegenüber viel zu viel Gnade gezeigt, Kommandant.\n\nWenn Ihr erlaubt, ich habe einen Zauberspruch perfektioniert, der ihnen demonstrieren wird, was geschieht, wenn man sich uns in den Weg stellt.Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
quests[37082] = { id = 37082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Gladiators", description = "Euer gnadenloses Wüten ist nicht unbemerkt geblieben, <Gladiator/Gladiatorin>. So viele Eurer Feinde sind durch Eure Kraft gefallen. Aufgrund Eurer unnachgiebigen Brutalität hat Kaiser Mar'gok höchstpersönlich um Eure Anwesenheit im großen Kolosseum von Hochfels gebeten. In Hochfels wartet ein Kampf epischen Ausmaßes.\n\nSolltet Ihr dem Ruf des Gladiators Folge leisten, übergebt dieses Siegel meinem Bruder Kharg. Er ist der Arenameister und befindet sich außerhalb des Kolosseums in Nagrand.", sourceObjective = "Bringt das Siegel von Hochfels zu Kharg außerhalb des Kolosseums von Hochfels in Nagrand.\n\nBereitgestellter Gegenstand:", completion = "Eine kühne Entscheidung, Gladiator. Die Meisten finden im Kolosseum nur den Tod. Hier zu überleben, ist mehr als nur eine Prüfung der Fähigkeiten, es ist ein Willenstest. Habt Ihr die Seelenstärke, um Champion zu werden?", sourceObjectiveStatus = "unverified-source-field" }
quests[37083] = { id = 37083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf, Sieg, Gruß!", description = "Die größten Gladiatoren von Draenor haben im Kolosseum um Ruhm und Ehre gekämpft. Werdet Ihr wie Kargath Messerfaust zu einer Legende werden oder werdet Ihr nichts weiter als Knochenstaub unter den Stiefeln eines noch gnadenloseren Gladiators sein? Es gibt nur einen Weg, das herauszufinden.\n\nIhr müsst zum Wettbewerb antreten und kämpfen! Der Preis des Sieges sind 100 Leben!\n\nIch werde Euch einmal pro Tag kostenlos Zugang gewähren, doch wenn Ihr versagt und erneut kämpfen wollt, müsst Ihr die Anmeldegebühr in Blut und Knochen zahlen!", sourceObjective = "Tötet 100 Gladiatoren im Kolosseum von Hochfels.\n\nIhr erhaltet Zugang zum Kolosseum, wenn Ihr mit Kharg in Hochfels oder in der Knochenschlucht bei Eurem Heiligtum des Gladiators sprecht.", completion = "Bemerkenswert! Ihr habt Euch als wahrer Gladiator erwiesen. Und einem wahren Gladiator widerfährt mehr als nur Ehre und Ruhm!", sourceObjectiveStatus = "unverified-source-field" }
quests[37084] = { id = 37084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schatten rufen", sourceObjective = "Die Schatten... Sie haben mir beigebracht, wie man sich in die Gedanken unserer Feinde einschleichen kann.\n\nJa... wie man Feinde auf die eigenen Leute hetzen kann. Unser Sieg wird nicht lange auf sich warten lassen. Krark!Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
quests[37085] = { id = 37085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorn des Klans", sourceObjective = "Unser Klan ist stark. Der stärkste.\n\nIch nähre unseren Hunger, mache uns stärker. Wir gewinnen!Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
quests[37086] = { id = 37086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wert im Verborgenen", description = "Hier in der Wiederverwertung sichten wir alle zusätzlichen Materialien, die Eure Anhänger von draußen mitbringen, um alles zu erhalten, was nützlich ist.\n\nIch habe von unseren Leuten eine Ladung Material bekommen, die ich noch nicht durchforsten konnte. Vielleicht könnt Ihr sie rüber zum Verbrenner bringen und nachschauen, ob etwas Verwertbares dabei ist?", sourceObjective = "Verwendet die kleine Tasche mit geborgenen Teilen in der Nähe des Verbrenners in Eurer Wiederverwertung.", progress = "Habt Ihr schon die Tasche mit den Teilen durchstöbern können?", completion = "Mehr war nicht drin? Aber das macht nichts. Manchmal gehen wir leer aus und manchmal ziehen wir das große Los.\n\nHier habe ich noch ein paar neue Sachen von unserem letzten Ausflug. Seht sie Euch an.\n\nViel Glück damit!", sourceObjectiveStatus = "unverified-source-field" }
quests[37087] = { id = 37087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschollen im Übergang", description = "<Mein Herr/Meine Dame>, das Lagerhaus ist komplett funktionsfähig. Ich habe mich darum gekümmert, dass Eure Vorräte sicher eingelagert und ausgewiesen sind.\n\nDummerweise musste ich im Zuge der weiteren Betriebsprüfung feststellen, dass uns ein paar Kisten mit überschüssigem Material abhandengekommen sind. Vermutlich hat einer von den Trägern sie verlegt.\n\nFalls Ihr bei Euren Runden auf überschüssige Kisten stoßt, bringt sie bitte zu mir, damit ich sie in unser Geschäftsbuch eintragen kann.", sourceObjective = "Sammelt 5 Kisten überschüssigen Materials.", progress = "Hallo Kommandant, was kann ich für Euch tun?", completion = "Laut Geschäftsbuch waren das alle, die uns gefehlt haben. Dafür werden die Träger heute Abend die Latrinen sauber machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[37088] = { id = 37088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das A und O des Handelns", description = "Um sich die Zeit zu vertreiben, nehmen Händler gerne ab und zu Getränke inspirierender Natur zu sich, wenn Ihr wisst, was ich meine.\n\nManchmal trinken sie ein wenig zu viel. Euer Händler könnte aus dem Tor gestolpert und irgendwo unter einem Baum umgekippt sein. Das kommt schon mal vor.\n\nZum Glück habe ich ein Getränk, um angeschlagene Händler wieder munter zu machen. Ein Tropfen und sie sind wieder äußerst arbeitswillig.", sourceObjective = "Findet den vermissten Händler und macht ihn wieder munter.", completion = "Jetzt habt Ihr eins meiner Berufsgeheimnisse erfahren, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[37091] = { id = 37091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Außergewöhnliche Erfindungen", description = "In der Werkstatt ist das Summen von Gehirnen und Motoren zu hören. Wir erfinden ständig etwas Neues.\n\nSchaut Euch die sensationelle Erfindung von heute auf der Werkbank hinter mir an.", sourceObjective = "Holt eine Erfindung von der Werkbank in der Gnomischen Werkstatt.", completion = "Nette Erfindung!", sourceObjectiveStatus = "unverified-source-field" }
quests[37092] = { id = 37092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alteisen", description = "Wenn Ihr alte Rüstungsteile der Eisernen Horde einsammelt, können wir im Zwergenbunker neue Ausrüstung daraus machen. Sie wird nicht die stärkste der Welt sein, sieht aber gut aus.\n\nBesorgt ein paar alte Rüstungsteile der Eisernen Horde und kommt wieder zu mir. Ich werde Euch einen schönen Wappenrock für Eure Bemühungen machen.", sourceObjective = "Sammelt 5 Rüstungsteile der Eisernen Horde von der Eisernen Horde in Draenor.", progress = "Habt Ihr die Rüstungsteile?", completion = "Diese Rüstungsteile werden genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37093] = { id = 37093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbukausbildung: Riesenhauer", description = "Euer Talbuk ist jetzt für weitere Aufgaben bereit. Und dazu soll er in seine Heimat, das Schattenmondtal, zurückkehren.\n\nEine der größten Kreaturen dieses Landes, der Riesenhauer, beansprucht das Tal für sich. Stellt Euch mit Eurem Reittier diesem Koloss. Wenn Ihr beide den Kampf überlebt, wird das Tier Vertrauen in seine Fähigkeiten entwickeln.", sourceObjective = "Besiegt Riesenhauer vom Rücken Eures Ausbildungstalbuks aus.", completion = "Das war in der Tat eine gute Kampfprüfung für Euren Talbuk. Er braucht jetzt etwas Ruhe, bevor wir mit der Ausbildung fortfahren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[37094] = { id = 37094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbukausbildung: Rakkiri", description = "Wir werden mit der Ausbildung Eures Talbuks gleich hier, in den eisigen Ebenen vom Frostfeuergrat, beginnen. Er braucht eine strenge Ausbildung, sonst wird er sich vielleicht in der Hitze des Gefechts erschrecken und davonlaufen.\n\nFindet in den gefrorenen Ebenen den großen Blutsauger, Rakkiri, und erledigt ihn vom Rücken Eures Talbuks aus. Dadurch gewöhnt er sich an Kampfeinsätze.", sourceObjective = "Besiegt Rakkiri vom Rücken Eures Ausbildungstalbuks aus.", completion = "Euer Talbuk wächst ja so schnell. Er braucht jetzt etwas Ruhe.", sourceObjectiveStatus = "unverified-source-field" }
quests[37095] = { id = 37095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbukausbildung: Sichelklaue", description = "Viele Tiere verstecken sich beim Anblick eines gefährlichen Raubtiers. Und im Gebiet der abgeschiedenen Klippen von Gorgrond lebt eines der gefährlichsten von ihnen. Das wird Eure nächste Herausforderung.\n\nReitet mit Eurem Tier zum Nest des mächtigen Sichelklaue und versucht, diesen gefährlichen Gegner zu erlegen.", sourceObjective = "Besiegt Sichelklaue vom Rücken Eures Ausbildungstalbuks aus.", completion = "Ein großer Sieg. Aber Euer Tier muss sich nun ausruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37096] = { id = 37096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbukausbildung: Gezz'ran", description = "Viele der Kreaturen Draenors konnten sich in einer höchst feindlichen Umgebung behaupten und entwickeln. Einer der gerissensten Jäger ist der Pirscher.\n\nPirscher können sich ihrer Umgebung anpassen und sich so anschleichen, um die Eier ihrer Beute zu stehlen. Versucht einmal, ob Ihr diesen natürlichen Verteidigungsmechanismus mit Eurem Tier überwinden könnt. In Talador findet Ihr ein solch angemessen gefährliches Raubtier als Gegner.", sourceObjective = "Besiegt Gezz'ran vom Rücken Eures Ausbildungstalbuks aus.", completion = "Das war eine gefährliche Bestie, die Ihr besiegt habt. Gute Arbeit, ich werde Eurem Reittier etwas Wasser geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[37097] = { id = 37097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbukausbildung: Bulbapore", description = "Weit unten im Süden, bei den Spitzen von Arak, ist das Land von Pilzen überschwemmt worden, die unter Wasser wachsen. In dem Gebiet vermehren sich jetzt überall ungebremst pilzartige Kreaturen.\n\nIndem Ihr den Kampf mit einer solch seltsamen Spezies wie dem Fungusgiganten Bulbapore aufnehmt, könnt Ihr testen, wie Euer Reittier auf ihm unbekannte Gegner reagiert.", sourceObjective = "Besiegt Bulbapore vom Rücken Eures Ausbildungstalbuks aus.", completion = "Ihr habt einen großen Sieg errungen. Ich werde jetzt Euer Reittier für die Nachtruhe bereit machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37098] = { id = 37098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbukausbildung: Grausame Oger", description = "In Nagrand sind die wildesten Bestien Draenors beheimatet. Und die Oger in dieser Gegend haben gelernt, diese Tiere mithilfe brutaler Techniken zu zähmen.\n\nDabei hat sich ein bestimmter Oger, der gorianische Tierpeitscher, durch besondere Grausamkeit und Blutlust ausgezeichnet. Nehmt es mit ihm auf, um zu sehen, wie Euer Tier auf ihn reagiert.", sourceObjective = "Besiegt den gorianischen Tierpeitscher vom Rücken Eures Ausbildungstalbuks aus.", completion = "Diese Tiere erholen sich sehr schnell. Wir wollen uns jetzt auch zur Nachtruhe begeben. Ihr habt Euch tapfer geschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37099] = { id = 37099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbukausbildung: Nachtflügelwindroc", description = "Die Windrocs von Nagrand sind gerissene Jäger, die oftmals im Schwarm auf unaufmerksame Beute niederstoßen. Wenn Euer Tier nicht lernt, auch den Luftraum im Auge zu behalten, wird es schon bald keines mehr haben.\n\nBegebt Euch nach Nagrand und nehmt es mit dem stärksten Windroc auf, dem Nachtflügelwindroc. Das sollte eine würdige Prüfung für Euer Reittier sein.", sourceObjective = "Besiegt den Nachtflügelwindroc vom Rücken Eures Ausbildungstalbuks aus.", completion = "Von jetzt an wird Euer Reittier ganz sicher daran denken, den Himmel im Auge zu behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[37100] = { id = 37100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbukausbildung: Zornmotte", description = "Tief in den Wäldern von Nagrand leben ein paar Tiere, die selbst den gefährlichsten Raubtieren entkommen können. Das größte dieser Tiere ist die Zornmotte. Sie ist mit einem übel riechenden Staub bedeckt.\n\nWenn dieser Mottenstaub sogar die Wölfe abschrecken kann, wird dies ein guter Test für Euren Talbuk. Sorgt dafür, dass er sich nicht davon ablenken lässt, und schaltet diese Motte aus.", sourceObjective = "Besiegt die Zornmotte vom Rücken Eures Ausbildungstalbuks aus.", completion = "Schön, dass Ihr zurück seid. Es wird eine Weile dauern, diesen Staub wieder loszuwerden.", sourceObjectiveStatus = "unverified-source-field" }
quests[37101] = { id = 37101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbukausbildung: Donnersturm", description = "Die Naturgewalten stellen für einige Tiere oftmals ein Problem dar. Selbst der mächtigste Wolf versteckt sich manchmal, wenn er das Donnern in der Ferne hört.\n\nIn Nagrand, auf einem windumpeitschten Kliff hoch über der Küste, lebt eine Kreatur, die aus reinem Unwetter besteht. Schwingt Euch auf den Rücken Eures Tieres, um gegen Donnersturm anzutreten. Dann werden wir ja erleben, wie sich Euer Tier verhält.", sourceObjective = "Besiegt Donnersturm vom Rücken Eures Ausbildungstalbuks aus.", completion = "Euer Reittier ist ein bisschen nass, aber ansonsten ganz vergnügt. Ich werde es trocknen und dann dafür sorgen, dass es ruht.", sourceObjectiveStatus = "unverified-source-field" }
quests[37102] = { id = 37102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbukausbildung: Eisenfräser", description = "So, Ihr habt bis jetzt Feinde in der Luft, an Land und sogar im Unwetter besiegt. Aber jetzt geht es gegen Kreaturen, die sich unter Euren Füßen befinden.\n\nDer Felswurm ist ein gerissener Jäger, der seine Beute aus dem sandigen Untergrund heraus angreift. Viele Tiere Nagrands werden daher durch Erschütterungen der Erde erschreckt. Begebt Euch mit Eurem Reittier zu den sandigen Gestaden und versucht, einen der älteren Felswürmer auszuschalten: Eisenfräser.", sourceObjective = "Besiegt Eisenfräser vom Rücken Eures Ausbildungstalbuks aus.", completion = "Ihr steht auf sicheren Beinen, auch wenn die Erde bebt. Bewundernswert.\n\nGönnt jetzt Eurem Reittier die verdiente Nachtruhe.", sourceObjectiveStatus = "unverified-source-field" }
quests[37103] = { id = 37103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbukausbildung: Orcjäger", description = "In den Reihen des Kriegshymnenklans in Nagrand gibt es einige der besten Jäger von ganz Draenor. Ihre Bestientöter stellen eine anspruchsvolle Prüfung für Euer Reittier dar.\n\nDa draußen in Nagrand gibt es einen Orc. Er nennt sich Karak der Großjäger. Er hat mehr wilde Bestien erlegt als alle anderen seines Klans. Reitet ihm auf Eurem Reittier entgegen und schaltet ihn aus, um all seine Opfer zu rächen.", sourceObjective = "Besiegt Karak den Großjäger vom Rücken Eures Ausbildungstalbuks aus.", completion = "Ah, Ihr habt den Jäger gejagt. Damit habt Ihr vielen Kreaturen einen guten Dienst erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37104] = { id = 37104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbukausbildung: Der Garn", description = "In der letzten Prüfung für Euer Reittier geht es gegen eine der schrecklichsten Kreaturen dieses Landes.\n\nMan nennt sie die \"Garn\". Diese nachtschwarzen Wölfe sind doppelt so groß wie normale Wölfe und können einen Orc in Sekundenschnelle in Stücke reißen. Die Tiere dieser Gegend haben vollkommen zu Recht Angst vor ihnen.\n\nDa draußen streift ein einsamer Garn umher, der Nagrand zu seiner Heimat gemacht hat. Schwingt Euch auf Euren Talbuk und schaltet ihn aus. Wenn Ihr beide überlebt, wird Euer Talbuk wahrhaft für den Krieg bereit sein.", sourceObjective = "Besiegt Malmkiefer vom Rücken Eures Ausbildungstalbuks aus.", completion = "Euer ohnehin schon kräftiger und schneller Gefährte hat jetzt auch die Angst vor anderen Kreaturen verloren. Ihr habt ausgezeichnete Arbeit bei der Ausbildung geleistet. Ich überreiche Euch mit Freuden die Zügel.", sourceObjectiveStatus = "unverified-source-field" }
quests[37105] = { id = 37105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolfsausbildung: Grausame Oger", description = "Die Wölfe dieses Landes sind die wildesten Tiere, die ich kenne. Und gewiss haben sie keine Angst vor Orcs und Ogern.\n\nWir wollen Euren Wolf mal auf einen der Oger loslassen, die Ihr ja schon kennt. Probiert mal aus, wie er auf den nach Blut und Angst stinkenden gorianischen Tierpeitscher reagiert.", sourceObjective = "Besiegt den gorianischen Tierpeitscher vom Rücken Eures Ausbildungsknurrers aus.", completion = "Diese Tiere erholen sich sehr schnell. Wir wollen uns jetzt auch zur Nachtruhe begeben. Ihr habt Euch tapfer geschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37106] = { id = 37106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolfsausbildung: Nachtflügelwindroc", description = "Die Windrocs von Nagrand sind gerissene Jäger, die oftmals im Schwarm auf unaufmerksame Beute niederstoßen. Wenn Euer Tier nicht lernt, auch den Luftraum im Auge zu behalten, wird es schon bald keines mehr haben.\n\nBegebt Euch nach Nagrand und nehmt es mit dem stärksten Windroc auf, dem Nachtflügelwindroc. Das sollte eine würdige Prüfung für Euer Reittier sein.", sourceObjective = "Besiegt den Nachtflügelwindroc vom Rücken Eures Ausbildungsknurrers aus.", completion = "Von jetzt an wird Euer Reittier ganz sicher daran denken, den Himmel im Auge zu behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[37107] = { id = 37107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolfsausbildung: Zornmotte", description = "Tief in den Wäldern von Nagrand leben ein paar Tiere, die selbst den gefährlichsten Raubtieren entkommen können. Das größte dieser Tiere ist die Zornmotte. Sie ist mit einem übel riechenden Staub bedeckt.\n\nWenn dieser Mottenstaub sogar die Wölfe abschrecken kann, wird dies ein guter Test für Euer Tier. Sorgt dafür, dass es sich nicht davon ablenken lässt, und schaltet diese Motte aus.", sourceObjective = "Besiegt die Zornmotte vom Rücken Eures Ausbildungsknurrers aus.", completion = "Schön, dass Ihr zurück seid. Es wird eine Weile dauern, diesen Staub wieder loszuwerden.", sourceObjectiveStatus = "unverified-source-field" }
quests[37108] = { id = 37108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolfsausbildung: Donnersturm", description = "Die Naturgewalten stellen für einige Tiere oftmals ein Problem dar. Selbst der mächtigste Wolf versteckt sich manchmal, wenn er das Donnern in der Ferne hört.\n\nIn Nagrand, auf einem windumpeitschten Kliff hoch über der Küste, lebt eine Kreatur, die aus reinem Unwetter besteht. Schwingt Euch auf den Rücken Eures Tieres, um gegen Donnersturm anzutreten. Dann werden wir ja erleben, wie sich Euer Tier verhält.", sourceObjective = "Besiegt Donnersturm vom Rücken Eures Ausbildungsknurrers aus.", completion = "Euer Reittier ist ein bisschen nass, aber ansonsten ganz vergnügt. Ich werde es trocknen und dann dafür sorgen, dass es ruht.", sourceObjectiveStatus = "unverified-source-field" }
quests[37109] = { id = 37109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolfsausbildung: Eisenfräser", description = "So, Ihr habt bis jetzt Feinde in der Luft, an Land und sogar im Unwetter besiegt. Aber jetzt geht es gegen Kreaturen, die sich unter Euren Füßen befinden.\n\nDer Felswurm ist ein gerissener Jäger, der seine Beute aus dem sandigen Untergrund heraus angreift. Viele Tiere Nagrands werden daher durch Erschütterungen der Erde erschreckt. Begebt Euch mit Eurem Reittier zu den sandigen Gestaden und versucht, einen der älteren Felswürmer auszuschalten: Eisenfräser.", sourceObjective = "Besiegt Eisenfräser vom Rücken Eures Ausbildungsknurrers aus.", completion = "Ihr steht auf sicheren Beinen, auch wenn die Erde bebt. Bewundernswert.\n\nGönnt jetzt Eurem Reittier die verdiente Nachtruhe.", sourceObjectiveStatus = "unverified-source-field" }
quests[37110] = { id = 37110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolfsausbildung: Orcjäger", description = "In den Reihen des Kriegshymnenklans in Nagrand gibt es einige der besten Jäger von ganz Draenor. Ihre Bestientöter stellen eine anspruchsvolle Prüfung für Euer Reittier dar.\n\nDa draußen in Nagrand gibt es einen Orc. Er nennt sich Karak der Großjäger. Er hat mehr wilde Bestien erlegt als alle anderen seines Klans. Reitet ihm auf Eurem Reittier entgegen und schaltet ihn aus, um all seine Opfer zu rächen.", sourceObjective = "Besiegt Karak den Großjäger vom Rücken Eures Ausbildungsknurrers aus.", completion = "Ah, Ihr habt den Jäger gejagt. Damit habt Ihr vielen Kreaturen einen guten Dienst erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
